'use client';

import { QueryClient, QueryClientContext, QueryClientProvider } from '@tanstack/react-query';
import { type LucideIcon, Rows3 } from 'lucide-react';
import * as React from 'react';

import type { AnyResource, ResourceRef, ResourceRouter } from '@/components/ui/resource-kit/types';

type ResourceKitContextValue = {
	router: ResourceRouter;
	resources: readonly AnyResource[];
	byName: ReadonlyMap<string, AnyResource>;
	locale: string;
	currency: string;
	/** Fixed clock for relative dates, in epoch milliseconds; undefined reads the system clock. */
	now: number | undefined;
	icons: Readonly<Record<string, LucideIcon>>;
};

const ResourceKitContext = React.createContext<ResourceKitContextValue | null>(null);

export type ResourceKitProviderProps = {
	router: ResourceRouter;
	resources: readonly AnyResource[];
	/** Reuses the host's client. Without one the provider uses the enclosing client, or makes its own. */
	queryClient?: QueryClient;
	/** Number and date formatting. Defaults to en-US. */
	locale?: string;
	/** ISO code for `currency` fields. Defaults to USD. */
	currency?: string;
	/** A fixed clock for relative dates ("3 days ago"), e.g. from the server; defaults to the reader's clock. */
	now?: string | number | Date;
	/** Icon components for the names resources use in `icon`, e.g. `{ calendar: Calendar }`. */
	icons?: Readonly<Record<string, LucideIcon>>;
	children: React.ReactNode;
};

/** `CalendarDays`, `calendar_days`, and `calendar-days` all name the same icon. */
const iconKey = (name: string) => name.replace(/([a-z0-9])([A-Z])/g, '$1-$2').replace(/[\s_]+/g, '-').toLowerCase();

function createQueryClient() {
	return new QueryClient({ defaultOptions: { queries: { staleTime: 30_000, retry: 1, refetchOnWindowFocus: false } } });
}

/**
 * Holds the resources, the host router, and the query cache every resource
 * screen reads through. Relation targets resolve here by name.
 */
export function ResourceKitProvider({ router, resources, queryClient, locale = 'en-US', currency = 'USD', now, icons, children }: ResourceKitProviderProps) {
	const outerClient = React.useContext(QueryClientContext);
	const [ownClient] = React.useState(() => (queryClient || outerClient ? null : createQueryClient()));
	// A Date prop is a new object each render; its time is what matters.
	const nowMs = now === undefined ? undefined : new Date(now).getTime();
	const value = React.useMemo<ResourceKitContextValue>(
		() => ({
			router,
			resources,
			byName: new Map(resources.map((resource) => [resource.name, resource])),
			locale,
			currency,
			now: nowMs,
			icons: Object.fromEntries(Object.entries(icons ?? {}).map(([name, icon]) => [iconKey(name), icon])),
		}),
		[router, resources, locale, currency, nowMs, icons],
	);
	const content = <ResourceKitContext.Provider value={value}>{children}</ResourceKitContext.Provider>;
	const client = queryClient ?? ownClient;
	return client ? <QueryClientProvider client={client}>{content}</QueryClientProvider> : content;
}

export function useResourceKit(): ResourceKitContextValue {
	const context = React.useContext(ResourceKitContext);
	if (!context) throw new Error('Resource Kit components must render inside <ResourceKitProvider>.');
	return context;
}

/** The kit context when one encloses the caller, for components that also work alone. */
export function useOptionalResourceKit(): ResourceKitContextValue | null {
	return React.useContext(ResourceKitContext);
}

/** A resource by name or definition. */
export function useResourceDefinition(resource: ResourceRef): AnyResource {
	const { byName } = useResourceKit();
	if (typeof resource !== 'string') return resource;
	const definition = byName.get(resource);
	if (!definition) throw new Error(`Unknown resource "${resource}". Pass it to <ResourceKitProvider resources>.`);
	return definition;
}

/** The icon a resource names, from the provider's `icons` map, or a generic table glyph. */
export function useResourceIcon(resource: AnyResource): LucideIcon {
	const { icons } = useResourceKit();
	if (!resource.icon) return Rows3;
	return icons[iconKey(resource.icon)] ?? Rows3;
}

/** A resource's icon, sized for a row or heading. */
export function ResourceIcon({ resource, className }: { resource: ResourceRef; className?: string }) {
	const Icon = useResourceIcon(useResourceDefinition(resource));
	return <Icon aria-hidden="true" className={className} />;
}

'use client';

import { ArrowDownIcon, ArrowUpIcon, CircleAlertIcon, ExternalLinkIcon, MoreHorizontalIcon, PencilIcon, Trash2Icon } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { focusRingClass, pressClass } from '@/components/ui/workspace-kit/primitives';
import { TableSurface, tableHeadClass, tableRowClass } from '@/components/ui/workspace-kit/surface';
import { useResourceDefinition, useResourceKit } from '@/components/ui/resource-kit/context';
import { FieldValue, LabelSkeleton, linkClass } from '@/components/ui/resource-kit/field-value';
import { fieldFormat, isSortable, NUMERIC_FORMATS, recordId, visibleFields } from '@/components/ui/resource-kit/fields';
import { formatFieldText } from '@/components/ui/resource-kit/format';
import { useRelationLabels, useRowTitles } from '@/components/ui/resource-kit/labels';
import type { ListQuery, ResourceField, ResourceRef, ResourceRow } from '@/components/ui/resource-kit/types';

type Sort = NonNullable<ListQuery['sort']>;

export type DataTableProps = {
	resource: ResourceRef;
	rows: readonly ResourceRow[];
	/** Column field names; defaults to the resource's `columns`. */
	columns?: readonly string[];
	sort?: Sort;
	/** Makes plain columns sortable from their headers. */
	onSortChange?: (sort: Sort) => void;
	onEdit?: (row: ResourceRow) => void;
	onDelete?: (row: ResourceRow) => void;
	loading?: boolean;
	/** Rows the skeleton draws while loading. */
	skeletonRows?: number;
	/** Shown in the body when there are no rows. */
	emptyLabel?: React.ReactNode;
	/** A failed load, announced above the rows (or in their place when there are none). */
	error?: React.ReactNode;
	className?: string;
};

const MENU_ITEM = 'gap-2 [&_svg]:size-3.5 [&_svg]:text-muted-foreground';

/**
 * Columns fold away as the table narrows: the first two always show, the next
 * two from a 36rem container, two more from 56rem, the rest from 72rem. Folded values are summarised
 * under the first cell, so a phone or a narrow pane still reads each record.
 */
function foldClass(index: number) {
	if (index < 2) return undefined;
	if (index < 4) return 'hidden @xl/table:table-cell';
	return index < 6 ? 'hidden @4xl/table:table-cell' : 'hidden @6xl/table:table-cell';
}

/** Badges, numbers, and dates: always short, so their columns fit the value and never cut it. */
const SHORT_FORMATS = new Set(['badge', 'boolean', 'number', 'currency', 'percent', 'date', 'datetime', 'relative']);
/** Free text and relations fit their value up to a width that grows with the table. */
const TEXT_CAP = 'max-w-24 @md/table:max-w-28 @3xl/table:max-w-36 @5xl/table:max-w-48 @7xl/table:max-w-64';

/**
 * How a column takes space. The first column is the flexible one: it takes
 * whatever the table has left and truncates only when the pane is narrow.
 * Short values size to their content. Free text and relations size to their
 * content up to a cap, then truncate.
 */
function columnClasses(field: ResourceField, index: number): { cell: string; value?: string } {
	if (index === 0) return { cell: 'w-full min-w-24 @md/table:min-w-32' };
	const format = fieldFormat(field);
	if (field.relation?.many || !SHORT_FORMATS.has(format)) return { cell: 'w-px', value: TEXT_CAP };
	// A badge holds a short label, but an unknown value from the database can be long.
	if (format === 'badge') return { cell: 'w-px whitespace-nowrap', value: 'max-w-36' };
	return { cell: cn('w-px whitespace-nowrap', NUMERIC_FORMATS.has(format) && 'text-end') };
}

function SortableHeader({ field, index, sort, onSortChange }: { field: ResourceField; index: number; sort?: Sort; onSortChange?: (sort: Sort) => void }) {
	const active = sort?.field === field.name;
	const Caret = sort?.direction === 'asc' ? ArrowUpIcon : ArrowDownIcon;
	const sortable = Boolean(onSortChange) && isSortable(field);
	return (
		<th scope="col" aria-sort={active ? (sort!.direction === 'asc' ? 'ascending' : 'descending') : undefined} className={cn(columnClasses(field, index).cell, foldClass(index))}>
			{sortable ? (
				<button
					type="button"
					onClick={() => onSortChange!({ field: field.name, direction: active && sort!.direction === 'asc' ? 'desc' : 'asc' })}
					className={cn(
						'-mx-1 inline-flex cursor-pointer items-center gap-1 rounded px-1 hover:text-foreground',
						index === 0 && 'max-w-full',
						active && 'text-foreground',
						index > 0 && NUMERIC_FORMATS.has(fieldFormat(field)) && 'flex-row-reverse',
						focusRingClass,
					)}
				>
					<span title={field.label} className="max-w-40 truncate">
						{field.label}
					</span>
					{active ? <Caret aria-hidden="true" className="size-3 shrink-0" /> : null}
				</button>
			) : (
				<span title={field.label} className="block max-w-40 truncate">
					{field.label}
				</span>
			)}
		</th>
	);
}

/**
 * A page of records on the workspace table surface: cells formatted by field,
 * option badges, relation labels that link to the related record, and an
 * actions menu per row. Sorting is controlled; the table never fetches pages.
 */
export function DataTable({ resource: resourceRef, rows, columns, sort, onSortChange, onEdit, onDelete, loading, skeletonRows = 6, emptyLabel = 'Nothing here yet.', error, className }: DataTableProps) {
	const resource = useResourceDefinition(resourceRef);
	const { router, locale, currency, now } = useResourceKit();
	const fields = React.useMemo(() => visibleFields(resource, columns ?? resource.columns), [resource, columns]);
	const relationLabel = useRelationLabels(fields, rows);
	const titleOf = useRowTitles(resource, rows);
	const columnCount = fields.length + 1;

	if (loading) return <DataTableSkeleton fields={fields} rows={skeletonRows} className={className} />;

	/** Text for a folded column in the summary line under the first cell. */
	const summary = (field: ResourceField, row: ResourceRow) => {
		if (field.input === 'relation') return field.relation?.many ? null : relationLabel(field, row)?.label ?? null;
		return formatFieldText(field, row[field.name], { locale, currency, now, compact: true });
	};

	return (
		<TableSurface minWidth="18rem" className={cn('@container/table', className)}>
			<caption className="sr-only">{resource.label}</caption>
			<thead className={tableHeadClass}>
				<tr>
					{fields.map((field, index) => (
						<SortableHeader key={field.name} field={field} index={index} sort={sort} onSortChange={onSortChange} />
					))}
					<th scope="col" className="w-12">
						<span className="sr-only">Actions</span>
					</th>
				</tr>
			</thead>
			<tbody>
				{error ? (
					<tr className={tableRowClass}>
						<td colSpan={columnCount} role="alert" className="text-destructive [overflow-wrap:anywhere]">
							<span className="flex items-start gap-2">
								<CircleAlertIcon aria-hidden="true" className="mt-0.5 size-3.5 shrink-0" />
								{error}
							</span>
						</td>
					</tr>
				) : null}
				{rows.length === 0 && !error ? (
					<tr className={tableRowClass}>
						<td colSpan={columnCount} className="h-24 text-center text-muted-foreground">
							{emptyLabel}
						</td>
					</tr>
				) : (
					rows.map((row, rowIndex) => {
						const id = recordId(resource, row);
						const title = titleOf(row);
						const name = title ?? id;
						const href = router.detailHref(resource.name, id);
						const folded = fields
							.slice(2, 4)
							.map((field) => summary(field, row))
							.filter((text): text is string => Boolean(text));
						return (
							<tr
								key={id || rowIndex}
								onClick={(event) => {
									if ((event.target as HTMLElement).closest('a, button, [role="menuitem"]')) return;
									router.navigate(href);
								}}
								className={cn(tableRowClass, 'group/row cursor-pointer transition-colors duration-(--duration-fast) hover:bg-overlay-hover')}
							>
								{fields.map((field, index) => (
									<td key={field.name} className={cn(columnClasses(field, index).cell, index > 0 && 'text-muted-foreground', foldClass(index))}>
										{index === 0 ? (
											// Zero width with a full-width floor: the title adds nothing to the column's size, so the column takes what is left.
											<span className="flex w-0 min-w-full flex-col">
												{field.name === resource.titleField ? (
													<router.Link href={href} className={cn(linkClass, 'block min-w-0 font-medium hover:no-underline')}>
														{title === null ? (
															<LabelSkeleton />
														) : (
															<span dir="auto" title={title} className="block truncate">
																{title}
															</span>
														)}
													</router.Link>
												) : (
													<FieldValue resource={resource} field={field} row={row} relation={relationLabel(field, row)} truncate className="font-medium text-foreground" />
												)}
												{folded.length > 0 ? (
													<span dir="auto" title={folded.join(' · ')} className="block truncate text-xs text-muted-foreground @xl/table:hidden">
														{folded.join(' · ')}
													</span>
												) : null}
											</span>
										) : (
											<FieldValue resource={resource} field={field} row={row} relation={relationLabel(field, row)} truncate className={columnClasses(field, index).value} />
										)}
									</td>
								))}
								<td className="text-end">
									<RowMenu title={name} href={href} onEdit={onEdit ? () => onEdit(row) : undefined} onDelete={onDelete ? () => onDelete(row) : undefined} />
								</td>
							</tr>
						);
					})
				)}
			</tbody>
		</TableSurface>
	);
}

function RowMenu({ title, href, onEdit, onDelete }: { title: string; href: string; onEdit?: () => void; onDelete?: () => void }) {
	const { router } = useResourceKit();
	return (
		<div className="flex justify-end opacity-0 transition-opacity duration-(--duration-fast) group-hover/row:opacity-100 group-focus-within/row:opacity-100 has-[[data-popup-open]]:opacity-100 pointer-coarse:opacity-100">
			<DropdownMenu>
				<DropdownMenuTrigger
					aria-label={`Actions for ${title}`}
					className={cn(
						'grid size-7 cursor-pointer place-items-center rounded-md text-muted-foreground hover:bg-overlay-hover hover:text-foreground data-[popup-open]:bg-overlay-hover',
						pressClass,
						focusRingClass,
					)}
				>
					<MoreHorizontalIcon aria-hidden="true" className="size-3.5" />
				</DropdownMenuTrigger>
				<DropdownMenuContent align="end" className="w-40">
					<DropdownMenuItem className={MENU_ITEM} onClick={() => router.navigate(href)}>
						<ExternalLinkIcon aria-hidden="true" />
						Open
					</DropdownMenuItem>
					{onEdit ? (
						<DropdownMenuItem className={MENU_ITEM} onClick={onEdit}>
							<PencilIcon aria-hidden="true" />
							Edit
						</DropdownMenuItem>
					) : null}
					{onDelete ? (
						<>
							<DropdownMenuSeparator />
							<DropdownMenuItem variant="destructive" className={MENU_ITEM} onClick={onDelete}>
								<Trash2Icon aria-hidden="true" />
								Delete
							</DropdownMenuItem>
						</>
					) : null}
				</DropdownMenuContent>
			</DropdownMenu>
		</div>
	);
}

const SKELETON_WIDTHS = ['w-36', 'w-24', 'w-44', 'w-28', 'w-32', 'w-20'];

/** Loading rows in the table's own layout, so the page does not jump when data lands. */
export function DataTableSkeleton({ fields, rows = 6, className }: { fields: readonly ResourceField[]; rows?: number; className?: string }) {
	return (
		<TableSurface minWidth="18rem" className={cn('@container/table', className)}>
			<thead className={tableHeadClass}>
				<tr>
					{fields.map((field, index) => (
						<th key={field.name} scope="col" className={cn(columnClasses(field, index).cell, foldClass(index))}>
							<span className="block max-w-40 truncate">{field.label}</span>
						</th>
					))}
					<th className="w-12" />
				</tr>
			</thead>
			<tbody aria-busy="true" aria-label="Loading" className="motion-safe:animate-pulse">
				{Array.from({ length: rows }, (_, rowIndex) => (
					<tr key={rowIndex} className={tableRowClass}>
						{fields.map((field, index) => (
							<td key={field.name} className={foldClass(index)}>
								<span className={cn('block h-2.5 rounded-full bg-muted', index === 0 ? SKELETON_WIDTHS[rowIndex % SKELETON_WIDTHS.length] : 'w-16')} />
							</td>
						))}
						<td />
					</tr>
				))}
			</tbody>
		</TableSurface>
	);
}

'use client';

import * as React from 'react';

import {
	AlertDialog,
	AlertDialogCancel,
	AlertDialogContent,
	AlertDialogDescription,
	AlertDialogFooter,
	AlertDialogHeader,
	AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import { Spinner } from '@/components/ui/spinner';
import { useResourceDefinition } from '@/components/ui/resource-kit/context';
import { inSentence, recordId } from '@/components/ui/resource-kit/fields';
import { describeSaveFailure, type SaveFailure } from '@/components/ui/resource-kit/form-values';
import { useRowTitles } from '@/components/ui/resource-kit/labels';
import { useDeleteRecord } from '@/components/ui/resource-kit/queries';
import { SaveFailureAlert } from '@/components/ui/resource-kit/failures';
import type { ResourceRef, ResourceRow } from '@/components/ui/resource-kit/types';

export type DeleteDialogProps = {
	resource: ResourceRef;
	/** The record to delete. Keep it set while the dialog closes so its copy does not blank out. */
	record: ResourceRow | null;
	open: boolean;
	onOpenChange: (open: boolean) => void;
	onDeleted?: (id: string) => void;
};

/**
 * Confirms and deletes one record. Stays open with the source's message when
 * the delete is rejected (a foreign key, a policy), so nothing fails silently.
 */
export function DeleteDialog({ resource: resourceRef, record, open, onOpenChange, onDeleted }: DeleteDialogProps) {
	const resource = useResourceDefinition(resourceRef);
	const remove = useDeleteRecord(resource);
	const [error, setError] = React.useState<SaveFailure | null>(null);
	const titleOf = useRowTitles(resource, record ? [record] : []);
	const title = record ? (titleOf(record) ?? '…') : '';
	const noun = inSentence(resource.singular);

	const changeOpen = (next: boolean) => {
		if (remove.isPending) return;
		if (!next) setError(null);
		onOpenChange(next);
	};

	const confirm = async () => {
		if (!record) return;
		const id = recordId(resource, record);
		setError(null);
		try {
			await remove.mutateAsync(id);
			onOpenChange(false);
			onDeleted?.(id);
		} catch (cause) {
			setError(describeSaveFailure(cause, `The ${noun} could not be deleted. Try again.`));
		}
	};

	return (
		<AlertDialog open={open} onOpenChange={changeOpen}>
			<AlertDialogContent>
				<AlertDialogHeader>
					<AlertDialogTitle className="text-base font-medium">Delete this {noun}?</AlertDialogTitle>
					<AlertDialogDescription className="text-[0.8125rem] [overflow-wrap:anywhere]">
						<bdi className="font-medium text-foreground">{title}</bdi> will be permanently deleted. This can’t be undone.
					</AlertDialogDescription>
				</AlertDialogHeader>
				{error ? <SaveFailureAlert failure={error} /> : null}
				<AlertDialogFooter>
					<AlertDialogCancel disabled={remove.isPending}>Cancel</AlertDialogCancel>
					<Button variant="destructive" wrap disabled={remove.isPending} aria-busy={remove.isPending || undefined} onClick={() => void confirm()}>
						{remove.isPending ? <Spinner decorative className="size-4" /> : null}
						{remove.isPending ? 'Deleting…' : `Delete ${noun}`}
					</Button>
				</AlertDialogFooter>
			</AlertDialogContent>
		</AlertDialog>
	);
}

import { Building2, HandCoins, type LucideIcon, Tag, Users } from 'lucide-react';

import { createMemoryJunction, createMemorySource } from '@/components/ui/resource-kit/memory-source';
import { defineResource, type AnyResource } from '@/components/ui/resource-kit/types';

/** The demo's clock, so relative dates read the same everywhere. */
export const CRM_DEMO_NOW = '2026-10-19T09:00:00.000Z';

export type CrmCompany = { id: string; name: string; domain: string | null; industry: string | null; employees: number | null; annualRevenue: number | null; createdAt: string };
export type CrmContact = {
	id: string;
	fullName: string;
	email: string;
	phone: string | null;
	companyId: string | null;
	stage: string;
	birthday: string | null;
	lastContactedAt: string | null;
	notes: string | null;
	ownerId: string;
	createdAt: string;
};
export type CrmDeal = { id: string; title: string; companyId: string; contactId: string | null; amount: number; status: string; closeDate: string | null; probability: number | null; createdAt: string };
export type CrmTag = { id: string; name: string; createdAt: string };

export type CrmDemoData = {
	companies: CrmCompany[];
	contacts: CrmContact[];
	deals: CrmDeal[];
	tags: CrmTag[];
	/** Contact and tag ids linked through the junction. */
	contactTags: [string, string][];
};

/** A small deterministic generator, so the demo is identical on the server and in the browser. */
function seeded(seed: number) {
	let state = seed;
	return () => {
		state = (state * 1664525 + 1013904223) % 4294967296;
		return state / 4294967296;
	};
}

const FIRST = ['Ava', 'Noah', 'Mia', 'Liam', 'Zoe', 'Ethan', 'Isla', 'Leo', 'Nora', 'Kai', 'Ruth', 'Omar', 'Lena', 'Theo', 'Ines'];
const LAST = ['Patel', 'Nguyen', 'Garcia', 'Okafor', 'Schmidt', 'Rossi', 'Kim', 'Haddad', 'Silva', 'Novak', 'Larsen', 'Moreau'];
const COMPANIES = ['Northwind', 'Bluebird Labs', 'Harbor & Pine', 'Quill Health', 'Atlas Freight', 'Cobalt Bank', 'Juniper Retail', 'Orbit Robotics', 'Fable Foods', 'Meridian Energy'];
const INDUSTRIES = ['saas', 'retail', 'healthcare', 'finance', 'manufacturing'];
const STAGES = ['lead', 'qualified', 'customer', 'churned'];
const STATUSES = ['open', 'open', 'won', 'lost'];
const TAGS = ['Decision maker', 'Champion', 'Technical', 'Budget holder', 'Event lead', 'Renewal'];

const day = (offsetDays: number) => new Date(Date.parse(CRM_DEMO_NOW) + offsetDays * 86_400_000).toISOString();
const slug = (text: string) => text.toLowerCase().replace(/[^a-z0-9]+/g, '');

/** The demo's rows: ten companies, their contacts and deals, and tags on contacts. */
export function crmDemoData(): CrmDemoData {
	const random = seeded(7);
	const pick = <T>(list: readonly T[]) => list[Math.floor(random() * list.length)]!;
	const companies: CrmCompany[] = COMPANIES.map((name, index) => ({
		id: `co-${index + 1}`,
		name,
		domain: `https://${slug(name)}.example.com`,
		industry: INDUSTRIES[index % INDUSTRIES.length]!,
		employees: Math.round(20 + random() * 4000),
		annualRevenue: Math.round(500_000 + random() * 40_000_000),
		createdAt: day(-400 + index * 31),
	}));
	const contacts: CrmContact[] = Array.from({ length: 36 }, (_, index) => {
		const first = FIRST[index % FIRST.length]!;
		const last = LAST[(index * 7) % LAST.length]!;
		const company = companies[index % companies.length]!;
		return {
			id: `ct-${index + 1}`,
			fullName: `${first} ${last}`,
			email: `${first}.${last}@${slug(company.name)}.example.com`.toLowerCase(),
			phone: index % 3 === 0 ? null : `+1 415 555 ${String(1000 + index * 37).slice(-4)}`,
			companyId: index % 11 === 10 ? null : company.id,
			stage: pick(STAGES),
			birthday: index % 4 === 0 ? `19${70 + (index % 25)}-0${1 + (index % 9)}-1${index % 9}` : null,
			lastContactedAt: index % 5 === 4 ? null : day(-Math.round(random() * 60)),
			notes: index % 4 === 1 ? 'Prefers email. Asked for a security review before the pilot.\nFollow up after the quarterly planning cycle.' : null,
			ownerId: 'user-1',
			createdAt: day(-300 + index * 7),
		};
	});
	const deals: CrmDeal[] = Array.from({ length: 24 }, (_, index) => {
		const contact = contacts[(index * 5) % contacts.length]!;
		const companyId = contact.companyId ?? companies[0]!.id;
		const company = companies.find((candidate) => candidate.id === companyId)!;
		return {
			id: `dl-${index + 1}`,
			title: `${company.name} ${pick(['renewal', 'expansion', 'pilot', 'platform deal', 'add-on seats'])}`,
			companyId,
			contactId: index % 6 === 5 ? null : contact.id,
			amount: Math.round(2_000 + random() * 180_000),
			status: STATUSES[index % STATUSES.length]!,
			closeDate: index % 7 === 6 ? null : day(-30 + Math.round(random() * 120)).slice(0, 10),
			probability: Math.round(random() * 100) / 100,
			createdAt: day(-200 + index * 6),
		};
	});
	const tags: CrmTag[] = TAGS.map((name, index) => ({ id: `tg-${index + 1}`, name, createdAt: day(-500 + index) }));
	const contactTags = contacts.flatMap((contact, index): [string, string][] =>
		index % 3 === 2 ? [] : [[contact.id, tags[index % tags.length]!.id], ...(index % 4 === 0 ? [[contact.id, tags[(index + 2) % tags.length]!.id] as [string, string]] : [])],
	);
	return { companies, contacts, deals, tags, contactTags };
}

