	url: 'url',
	date: 'date',
	datetime: 'datetime-local',
	time: 'time',
};

export type FieldControlProps = {
	field: ResourceField;
	value: FormValue;
	onChange: (value: FormValue) => void;
	id: string;
	invalid?: boolean;
	describedBy?: string;
	disabled?: boolean;
};

/** The currency symbol for the kit's locale and currency, e.g. "$" or "€". */
function useCurrencySymbol() {
	const { locale, currency } = useResourceKit();
	return React.useMemo(
		() => numberFormat(locale, { style: 'currency', currency }).formatToParts(0).find((part) => part.type === 'currency')?.value ?? currency,
		[locale, currency],
	);
}

/** The control that edits one field, chosen by its `input`. */
export function FieldControl({ field, value, onChange, id, invalid, describedBy, disabled }: FieldControlProps) {
	const symbol = useCurrencySymbol();
	const aria = { id, 'aria-invalid': invalid || undefined, 'aria-describedby': describedBy, disabled: disabled || field.readOnly };
	const text = typeof value === 'string' ? value : '';
	const placeholder = field.placeholder;

	// Text with a fixed set of options is edited as a choice.
	const input = field.options?.length && field.input === 'text' ? 'select' : field.input;
	switch (input) {
		case 'boolean':
			return <Switch id={id} aria-describedby={describedBy} disabled={aria.disabled} checked={value === true} onCheckedChange={(checked) => onChange(checked)} />;
		case 'textarea':
		case 'json':
			return (
				<Textarea
					{...aria}
					value={text}
					placeholder={placeholder}
					spellCheck={field.input === 'json' ? false : undefined}
					className={field.input === 'json' ? 'font-mono text-xs' : undefined}
					onChange={(event) => onChange(event.target.value)}
				/>
			);
		case 'currency':
			return (
				<InputGroup>
					<InputGroupAddon>
						<InputGroupText>{symbol}</InputGroupText>
					</InputGroupAddon>
					<InputGroupInput {...aria} inputMode="decimal" autoComplete="off" value={text} placeholder={placeholder ?? '0.00'} onChange={(event) => onChange(event.target.value)} />
				</InputGroup>
			);
		case 'number':
		case 'integer':
			return (
				<Input
					{...aria}
					inputMode={field.input === 'integer' ? 'numeric' : 'decimal'}
					autoComplete="off"
					value={text}
					placeholder={placeholder}
					className="tabular-nums"
					onChange={(event) => onChange(event.target.value)}
				/>
			);
		case 'select': {
			const options = field.options ?? [];
			const items: Record<string, string> = Object.fromEntries(options.map((option) => [option.value, option.label]));
			if (!field.required) items[NONE] = 'None';
			return (
				<Select value={text === '' ? (field.required ? null : NONE) : text} items={items} disabled={aria.disabled} onValueChange={(next) => onChange(next === NONE ? '' : next)}>
					<SelectTrigger id={id} aria-invalid={invalid || undefined} aria-describedby={describedBy} className="min-w-0">
						<SelectValue placeholder={placeholder ?? 'Choose…'} />
					</SelectTrigger>
					<SelectPopup>
						{field.required ? null : <SelectItem value={NONE}>None</SelectItem>}
						{options.map((option) => (
							<SelectItem key={option.value} value={option.value}>
								{option.label}
							</SelectItem>
						))}
					</SelectPopup>
				</Select>
			);
		}
		case 'relation': {
			if (!field.relation) return null;
			const shared = { resource: field.relation.resource, labelField: field.relation.labelField, id, invalid, 'aria-describedby': describedBy, disabled: aria.disabled, placeholder };
			return field.relation.many ? (
				<RelationPicker {...shared} multiple value={Array.isArray(value) ? value : []} onChange={(next) => onChange(next)} />
			) : (
				<RelationPicker {...shared} value={text || null} onChange={(next) => onChange(next ?? '')} />
			);
		}
		default:
			return (
				<Input
					{...aria}
					type={HTML_TYPE[field.input] ?? 'text'}
					autoComplete="off"
					spellCheck={field.input === 'uuid' || field.input === 'url' || field.input === 'email' ? false : undefined}
					className={field.input === 'uuid' ? 'font-mono' : undefined}
					value={text}
					placeholder={placeholder}
					onChange={(event) => onChange(event.target.value)}
				/>
			);
	}
}

'use client';

import { CheckIcon, CircleAlertIcon, MinusIcon } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { focusRingClass, ToneBadge } from '@/components/ui/workspace-kit/primitives';
import { useResourceKit } from '@/components/ui/resource-kit/context';
import { fieldFormat, isManyRelation, NUMERIC_FORMATS, recordId } from '@/components/ui/resource-kit/fields';
import { errorMessage } from '@/components/ui/resource-kit/form-values';
import { formatFieldText, optionFor } from '@/components/ui/resource-kit/format';
import { type RelationLabel, useRecordLabels } from '@/components/ui/resource-kit/labels';
import { queryFailure, useLinkedIds } from '@/components/ui/resource-kit/queries';
import type { AnyResource, ResourceField, ResourceRow } from '@/components/ui/resource-kit/types';

export const linkClass = cn('rounded-sm text-foreground underline-offset-4 hover:underline', focusRingClass);
const chipClass = cn(
	'inline-flex h-5 max-w-full min-w-0 items-center rounded-[5px] border border-border bg-muted/60 px-1.5 text-xs text-muted-foreground hover:text-foreground',
	focusRingClass,
);
const DATE_FORMATS = new Set(['date', 'datetime']);

/** A quiet dash for a value nobody set, named for screen readers. */
export function EmptyValue() {
	return (
		<span className="text-subtle-foreground">
			<span aria-hidden="true">—</span>
			<span className="sr-only">Not set</span>
		</span>
	);
}

/** A related record that could not be read: deleted, or not visible to this user. */
export function MissingValue({ id }: { id: string }) {
	return (
		<span title={id} className="text-subtle-foreground italic">
			Unavailable
		</span>
	);
}

/** A short shimmer where a label is still loading. */
export function LabelSkeleton({ className }: { className?: string }) {
	return <span aria-hidden="true" className={cn('inline-block h-2.5 w-20 rounded-full bg-muted align-middle motion-safe:animate-pulse', className)} />;
}

type FieldValueProps = {
	resource: AnyResource;
	field: ResourceField;
	row: ResourceRow;
	/** A resolved belongs-to label, from `useRelationLabels`. */
	relation?: RelationLabel | null;
	/** One line with an ellipsis (tables) instead of wrapping (detail). */
	truncate?: boolean;
	className?: string;
};

/** One field of a record as it reads: formatted text, an option badge, a yes/no, or links to related records. */
export function FieldValue({ resource, field, row, relation, truncate = false, className }: FieldValueProps) {
	const { locale, currency, now, router, byName } = useResourceKit();
	const lineClass = truncate ? 'block min-w-0 truncate' : 'min-w-0 [overflow-wrap:anywhere]';

	if (isManyRelation(field)) return <ManyRelationValue resource={resource} field={field} row={row} truncate={truncate} className={className} />;

	if (field.input === 'relation') {
		const target = field.relation ? byName.get(field.relation.resource) : undefined;
		if (!relation) return <EmptyValue />;
		if (relation.missing) return <MissingValue id={relation.id} />;
		if (relation.label === null) return <LabelSkeleton />;
		if (!target) return <span dir="auto" className={cn(lineClass, className)}>{relation.label}</span>;
		// The text carries `dir="auto"` on the element that truncates, so right-to-left labels end in an ellipsis, not a cut.
		return (
			<router.Link href={router.detailHref(target.name, relation.id)} className={cn(linkClass, 'block min-w-0', !truncate && 'inline', className)}>
				<span dir="auto" title={relation.label} className={lineClass}>
					{relation.label}
				</span>
			</router.Link>
		);
	}

	const value = row[field.name];
	if (value == null || value === '') return <EmptyValue />;
	const format = fieldFormat(field);

	if (format === 'badge') {
		const option = optionFor(field, value);
		const label = option?.label ?? String(value);
		return (
			<ToneBadge tone={option?.tone ?? 'neutral'} className={cn('max-w-full', className)}>
				<span dir="auto" title={label} className="min-w-0 truncate">
					{label}
				</span>
			</ToneBadge>
		);
	}

	if (format === 'boolean') {
		const on = value === true || value === 'true';
		const Icon = on ? CheckIcon : MinusIcon;
		return (
			<span className={cn('inline-flex items-center gap-1.5', on ? 'text-foreground' : 'text-muted-foreground', className)}>
				<Icon aria-hidden="true" className={cn('size-3.5 shrink-0', on ? 'text-success' : 'text-subtle-foreground')} />
				{on ? 'Yes' : 'No'}
			</span>
		);
	}

	const text = formatFieldText(field, value, { locale, currency, now, compact: truncate }) ?? '';
	// Compact cells drop the year and seconds; the full value stays one hover away.
	const full = truncate && DATE_FORMATS.has(format) ? (formatFieldText(field, value, { locale, currency, now }) ?? text) : text;
	if (field.input === 'url' && /^https?:\/\//i.test(text)) {
		return (
			<a href={text} target="_blank" rel="noreferrer" dir="ltr" title={text} className={cn(linkClass, lineClass, className)}>
				{text}
			</a>
		);
	}
	if (field.input === 'email') {
		return (
			<a href={`mailto:${text}`} dir="ltr" title={text} className={cn(linkClass, lineClass, className)}>
				{text}
			</a>
		);
	}
	return (
		<span
			title={truncate ? full : undefined}
			dir={NUMERIC_FORMATS.has(format) ? undefined : 'auto'}
			className={cn(
				lineClass,
				NUMERIC_FORMATS.has(format) && 'tabular-nums',
				field.input === 'json' && 'font-mono text-xs',
				field.input === 'textarea' && !truncate && 'whitespace-pre-wrap',
				className,
			)}
		>
			{text}
		</span>
	);
}

/** Linked records of a many-to-many field, from an array the source embedded or from `source.linked`. */
function ManyRelationValue({ resource, field, row, truncate, className }: { resource: AnyResource; field: ResourceField; row: ResourceRow; truncate: boolean; className?: string }) {
	const { byName, router } = useResourceKit();
	const target = byName.get(field.relation!.resource);
	const labelField = field.relation?.labelField ?? target?.titleField;
	const embedded = Array.isArray(row[field.name]) ? (row[field.name] as unknown[]) : null;
	const linked = useLinkedIds(resource, recordId(resource, row), field.name, { enabled: !embedded && Boolean(resource.source.linked) });
	const { ids, known } = React.useMemo(() => {
		const entries = (embedded ?? linked.data ?? []).map((item) => {
			if (item && typeof item === 'object') {
				const record = item as ResourceRow;
				const label = labelField ? record[labelField] : undefined;
				return { id: String(record[target?.primaryKey ?? 'id']), label: typeof label === 'string' ? label : undefined };
			}
			return { id: String(item), label: undefined };
		});
		return {
			ids: entries.map((entry) => entry.id),
			known: new Map(entries.flatMap((entry) => (entry.label ? [[entry.id, entry.label] as const] : []))),
		};
	}, [embedded, linked.data, labelField, target?.primaryKey]);
	const { labels, missing } = useRecordLabels(target, ids, labelField, known);

	const linkFailure = embedded ? null : queryFailure(linked);
	// A failed read is not "no links": say so, with the reason on hover.
	if (linkFailure && !linked.data) {
		return (
			<span title={errorMessage(linkFailure)} className={cn('inline-flex items-center gap-1 text-destructive', className)}>
				<CircleAlertIcon aria-hidden="true" className="size-3.5 shrink-0" />
				Couldn’t load
			</span>
		);
	}
	if (!embedded && linked.isPending && linked.fetchStatus !== 'idle') return <LabelSkeleton />;
	if (ids.length === 0) return <EmptyValue />;
	const shown = truncate ? ids.slice(0, 2) : ids;
	const rest = ids.length - shown.length;
	return (
		<span className={cn('flex min-w-0 gap-1', truncate ? 'flex-nowrap items-center' : 'flex-wrap', className)}>
			{shown.map((id) => {
				const label = labels.get(id);
				if (missing.has(id)) return <MissingValue key={id} id={id} />;
				if (label === undefined) return <LabelSkeleton key={id} className="w-12" />;
				return target ? (
					<router.Link key={id} href={router.detailHref(target.name, id)} className={chipClass}>
						<span dir="auto" title={label} className="min-w-0 truncate">
							{label}
						</span>
					</router.Link>
				) : (
					<span key={id} className={chipClass}>
						<span dir="auto" className="min-w-0 truncate">
							{label}
						</span>
					</span>
				);
			})}
			{rest > 0 ? <span className="shrink-0 text-xs text-muted-foreground tabular-nums">+{rest}</span> : null}
		</span>
	);
}

import type { AnyResource, FieldFormat, ResourceField, ResourceRow } from '@/components/ui/resource-kit/types';

/** The display format a field gets when its definition names none. */
export function fieldFormat(field: ResourceField): FieldFormat {
	if (field.format) return field.format;
	// A field with a fixed set of options reads as their badges, whatever control edits it.
	if (field.options?.length && field.input !== 'relation') return 'badge';
	switch (field.input) {
		case 'number':
		case 'integer':
			return 'number';
		case 'currency':
			return 'currency';
		case 'boolean':
			return 'boolean';
		case 'date':
			return 'date';
		case 'datetime':
			return 'datetime';
		case 'select':
			return 'badge';
		default:
			return 'text';
	}
}

/** Formats that read as figures: tabular digits, aligned to the end of a column. */
export const NUMERIC_FORMATS: ReadonlySet<FieldFormat> = new Set<FieldFormat>(['number', 'currency', 'percent']);

/** The named fields that exist and are not hidden, in the given order. */
export function visibleFields(resource: AnyResource, names: readonly string[]): ResourceField[] {
	return names.flatMap((name) => {
		const field = resource.fields[name];
		return field && !field.hidden ? [field] : [];
	});
}

/** Detail fields: the declared list, or every visible field in declaration order. */
export function detailFields(resource: AnyResource): ResourceField[] {
	return visibleFields(resource, resource.detailFields ?? Object.keys(resource.fields));
}

export const isManyRelation = (field: ResourceField) => field.input === 'relation' && Boolean(field.relation?.many);
export const isSingleRelation = (field: ResourceField) => field.input === 'relation' && Boolean(field.relation) && !field.relation?.many;

/** Fields a list can sort by: plain columns, not relations or JSON. */
export const isSortable = (field: ResourceField) => field.input !== 'relation' && field.input !== 'json';

/** The record id as a string. */
export function recordId(resource: AnyResource, row: ResourceRow): string {
	const value = row[resource.primaryKey];
	return value == null ? '' : String(value);
}

/** The text that names a record, falling back to its id. */
export function recordTitle(resource: AnyResource, row: ResourceRow | null | undefined, labelField = resource.titleField): string {
	if (!row) return '';
	const value = row[labelField];
	const text = typeof value === 'string' ? value.trim() : value == null ? '' : String(value);
	return text || recordId(resource, row) || `Untitled ${resource.singular}`;
}

/**
 * The key a source may embed a belongs-to row under: `companyId` and
 * `company_id` read `company`. Lets a list show relation labels without a
 * request per row when the source already joins them.
 */
export function embeddedKey(fieldName: string): string | null {
	const match = /^(.+?)(?:Id|_id)$/.exec(fieldName);
	return match ? match[1]! : null;
}

/** A belongs-to row the source embedded beside the foreign key, if any. */
export function embeddedRow(row: ResourceRow, field: ResourceField): ResourceRow | null {
	const key = embeddedKey(field.name);
	const value = key ? row[key] : undefined;
	return value && typeof value === 'object' && !Array.isArray(value) ? (value as ResourceRow) : null;
}

/** A has-many list on a record: another resource whose belongs-to field points back at it. */
export type HasManyRelation = { resource: AnyResource; field: ResourceField };

export function hasManyRelations(resource: AnyResource, all: readonly AnyResource[]): HasManyRelation[] {
	return all.flatMap((other) =>
		Object.values(other.fields)
			.filter((field) => isSingleRelation(field) && field.relation?.resource === resource.name)
			.map((field) => ({ resource: other, field })),
	);
}

/** Resources whose cached data can change when this one is written: its relation targets and everything pointing at it. */
export function relatedResourceNames(resource: AnyResource, all: readonly AnyResource[]): string[] {
	const names = new Set<string>([resource.name]);
	for (const field of Object.values(resource.fields)) {
		if (field.relation) names.add(field.relation.resource);
	}
	for (const other of all) {
		if (Object.values(other.fields).some((field) => field.relation?.resource === resource.name)) names.add(other.name);
	}
	return [...names];
}

/**
 * Lowercases a display label for use inside a sentence, leaving acronyms
 * ("CRM contacts") and single letters alone.
 */
export function inSentence(label: string): string {
	return /^\p{Lu}\p{Ll}/u.test(label) ? label.charAt(0).toLowerCase() + label.slice(1) : label;
}

import { isManyRelation } from '@/components/ui/resource-kit/fields';
import type { AnyResource, ResourceField, ResourceRow } from '@/components/ui/resource-kit/types';

/** What a form control holds: text, a toggle, or a set of linked ids. */
export type FormValue = string | boolean | string[];
export type FormValues = Record<string, FormValue>;
export type FormErrors = Record<string, string>;

export type FormMode = 'create' | 'edit';

/** The fields a form shows: writable ones always, read-only ones only when editing. */
export function formFieldsFor(resource: AnyResource, mode: FormMode): ResourceField[] {
	return resource.formFields.flatMap((name) => {
		const field = resource.fields[name];
		if (!field || field.hidden) return [];
		if (field.readOnly && mode === 'create') return [];
		return [field];
	});
}

const pad = (value: number) => String(value).padStart(2, '0');

/** An ISO timestamp as a `datetime-local` value in the reader's time zone. */
function toLocalDateTime(value: string): string {
	const date = new Date(value);
	if (Number.isNaN(date.getTime())) return '';
	return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

/** One stored value as its form control holds it. */
function toFormValue(field: ResourceField, value: unknown): FormValue {
	if (isManyRelation(field)) {
		return Array.isArray(value) ? value.map((item) => String(item && typeof item === 'object' ? (item as ResourceRow).id : item)) : [];
	}
	if (field.input === 'boolean') return value === true || value === 'true';
	if (value == null) return '';
	switch (field.input) {
		case 'date':
			return /^\d{4}-\d{2}-\d{2}/.exec(String(value))?.[0] ?? '';
		case 'datetime':
			return toLocalDateTime(String(value));
		case 'time':
			return String(value).slice(0, 5);
		case 'json':
			return typeof value === 'string' ? value : JSON.stringify(value, null, 2);
		default:
			return String(value);
	}
}

/**
 * The form's starting values: the record's (when editing), then any defaults
 * (e.g. the parent of a related list), then empty controls.
 */
export function initialFormValues(
	fields: readonly ResourceField[],
	record?: ResourceRow | null,
	defaults?: ResourceRow,
	linked?: Record<string, string[]>,
): FormValues {
	const values: FormValues = {};
	for (const field of fields) {
		const source = linked && isManyRelation(field) && field.name in linked ? linked[field.name] : record?.[field.name] ?? defaults?.[field.name];
		values[field.name] = toFormValue(field, source);
	}
	return values;
}

const isEmpty = (value: FormValue) => (Array.isArray(value) ? value.length === 0 : typeof value === 'string' ? value.trim() === '' : false);

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** Digits as typed, without grouping separators or spaces. */
const numeric = (text: string) => text.trim().replace(/[\s,]/g, '');

/** Why a value is not acceptable for its field, or nothing when it is. */
function fieldError(field: ResourceField, value: FormValue): string | undefined {
	if (isEmpty(value)) {
		if (!field.required || field.input === 'boolean') return undefined;
		return field.input === 'relation' || field.input === 'select' ? 'Choose an option.' : 'This field is required.';
	}
	if (typeof value !== 'string') return undefined;
	const text = value.trim();
	switch (field.input) {
		case 'number':
		case 'currency':
			return Number.isFinite(Number(numeric(text))) ? undefined : 'Enter a number.';
		case 'integer':
			return /^-?\d+$/.test(numeric(text)) ? undefined : 'Enter a whole number.';
		case 'email':
			return EMAIL.test(text) ? undefined : 'Enter an email address like name@example.com.';
		case 'url':
			try {
				new URL(text);
				return undefined;
			} catch {
				return 'Enter a full web address, like https://example.com.';
			}
		case 'uuid':
			return UUID.test(text) ? undefined : 'Enter a valid UUID.';
		case 'json':
			try {
				JSON.parse(text);
				return undefined;
			} catch {
				return 'Enter valid JSON.';
			}
		default:
			return undefined;
	}
}

/** Field errors keyed by field name; empty when the form can be saved. */
export function validateFormValues(fields: readonly ResourceField[], values: FormValues): FormErrors {
	const errors: FormErrors = {};
	for (const field of fields) {
		if (field.readOnly) continue;
		const message = fieldError(field, values[field.name] ?? '');
		if (message) errors[field.name] = message;
	}
	return errors;
}

/** A valid form value as the source stores it. Empty controls become null. */
function toStoredValue(field: ResourceField, value: FormValue): unknown {
	if (field.input === 'boolean') return value === true;
	if (typeof value !== 'string') return value;
	const text = field.input === 'textarea' ? value : value.trim();
	if (text.trim() === '') return null;
	switch (field.input) {
		case 'number':
		case 'currency':
			return Number(numeric(text));
		case 'integer':
			return Number.parseInt(numeric(text), 10);
		case 'json':
			return JSON.parse(text);
		case 'datetime':
			return new Date(text).toISOString();
		default:
			return text;
	}
}

export type LinkDiff = { add: string[]; remove: string[]; changed: boolean };

/** What changes between two sets of linked ids, ignoring order and duplicates. */
export function diffLinks(before: readonly string[], after: readonly string[]): LinkDiff {
	const was = new Set(before);
	const now = new Set(after);
	const add = [...now].filter((id) => !was.has(id));
	const remove = [...was].filter((id) => !now.has(id));
	return { add, remove, changed: add.length > 0 || remove.length > 0 };
}

export type Submission = {
	/** Column values for `create`, or only the changed ones for `update`. */
	values: ResourceRow;
	/** Many-to-many fields whose full set of linked ids must be written with `link`. */
	links: Record<string, string[]>;
};

const sameValue = (left: FormValue, right: FormValue) =>
	Array.isArray(left) && Array.isArray(right) ? !diffLinks(left, right).changed : left === right;

/**
 * Turns a valid form into what the source receives. Creating leaves out empty
 * optional fields so the database applies its defaults; editing sends only the
 * fields that changed (a cleared field as null) and re-links a many-to-many set
 * only when its members changed.
 */
export function buildSubmission(fields: readonly ResourceField[], values: FormValues, initial: FormValues, mode: FormMode, defaults?: ResourceRow): Submission {
	const submission: Submission = { values: {}, links: {} };
	// Defaults for columns the form does not show (the parent of a related list) still belong to a new record.
	if (mode === 'create' && defaults) {
		const shown = new Set(fields.map((field) => field.name));
		for (const [name, value] of Object.entries(defaults)) {
			if (!shown.has(name) && value !== undefined) submission.values[name] = value;
		}
	}
	for (const field of fields) {
		if (field.readOnly) continue;
		const value = values[field.name] ?? '';
		if (isManyRelation(field)) {
			const ids = [...new Set(value as string[])];
			if (mode === 'create' ? ids.length > 0 : diffLinks((initial[field.name] as string[]) ?? [], ids).changed) {
				submission.links[field.name] = ids;
			}
			continue;
		}
		if (mode === 'edit' && sameValue(value, initial[field.name] ?? '')) continue;
		const stored = toStoredValue(field, value);
		if (mode === 'create' && stored === null) continue;
		submission.values[field.name] = stored;
	}
	return submission;
}

/** Field messages a source attached to a rejected write, e.g. `{ fields: { email: 'Already taken.' } }`. */
export function serverFieldErrors(error: unknown): FormErrors {
	const fields = error && typeof error === 'object' ? (error as { fields?: unknown }).fields : undefined;
	if (!fields || typeof fields !== 'object') return {};
	return Object.fromEntries(Object.entries(fields).filter((entry): entry is [string, string] => typeof entry[1] === 'string'));
}

/** A readable message for a rejected request. */
export function errorMessage(error: unknown, fallback = 'Something went wrong. Try again.'): string {
	if (error instanceof Error && error.message.trim()) return error.message;
	if (typeof error === 'string' && error.trim()) return error;
	return fallback;
}

export type SaveFailure = {
	/** What the person reads first: the source's `userMessage`, or a plain sentence from the kit. */
	message: string;
	/** The source's own wording, kept out of the headline because it can carry server internals. */
	detail?: string;
	fields: FormErrors;
};

/**
 * How a rejected write is shown. A source can attach `fields` (messages under
 * inputs) and `userMessage` (a headline written for people); otherwise the
 * kit's sentence leads and the raw message is only a detail.
 */
export function describeSaveFailure(error: unknown, fallback: string): SaveFailure {
	const fields = serverFieldErrors(error);
	const userMessage = error && typeof error === 'object' ? (error as { userMessage?: unknown }).userMessage : undefined;
	if (typeof userMessage === 'string' && userMessage.trim()) return { message: userMessage, fields };
	if (Object.keys(fields).length > 0) return { message: 'Check the highlighted fields.', fields };
	const raw = errorMessage(error, '');
	return { message: fallback, detail: raw && raw !== fallback ? raw : undefined, fields };
}

import { dateFormat, numberFormat, relativeTimeFormat } from '@/lib/intl';
import { fieldFormat } from '@/components/ui/resource-kit/fields';
import type { FieldOption, ResourceField } from '@/components/ui/resource-kit/types';

export type FormatOptions = {
	locale: string;
	currency: string;
	now?: number;
	/** Short dates for table cells: "Oct 22, 6:00 PM", with the year only when it is not the current one. */
	compact?: boolean;
};

/** A number from a number or a numeric string (big numbers often arrive as text). */
export function toNumber(value: unknown): number | null {
	if (typeof value === 'number') return Number.isFinite(value) ? value : null;
	if (typeof value === 'string' && value.trim() !== '') {
		const parsed = Number(value);
		return Number.isFinite(parsed) ? parsed : null;
	}
	return null;
}

/** A date-only value (`2026-10-19`), read as that calendar day wherever the reader is. */
const DATE_ONLY = /^\d{4}-\d{2}-\d{2}$/;

function toDate(value: unknown): { date: Date; dateOnly: boolean } | null {
	if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : { date: value, dateOnly: false };
	if (typeof value !== 'string' && typeof value !== 'number') return null;
	const dateOnly = typeof value === 'string' && DATE_ONLY.test(value);
	const date = new Date(dateOnly ? `${value}T00:00:00Z` : value);
	return Number.isNaN(date.getTime()) ? null : { date, dateOnly };
}

const RELATIVE_STEPS: [Intl.RelativeTimeFormatUnit, number][] = [
	['year', 365 * 24 * 3600],
	['month', 30 * 24 * 3600],
	['week', 7 * 24 * 3600],
	['day', 24 * 3600],
	['hour', 3600],
	['minute', 60],
];

function relative(date: Date, { locale, now = Date.now() }: FormatOptions) {
	const seconds = (date.getTime() - now) / 1000;
	for (const [unit, size] of RELATIVE_STEPS) {
		if (Math.abs(seconds) >= size) return relativeTimeFormat(locale).format(Math.round(seconds / size), unit);
	}
	return relativeTimeFormat(locale).format(0, 'minute');
}

/** The option a stored select value names, if any. */
export function optionFor(field: ResourceField, value: unknown): FieldOption | undefined {
	return value == null ? undefined : field.options?.find((option) => option.value === String(value));
}

/**
 * A stored value as plain text for its field's format, or null when there is
 * nothing to show. Badges, booleans, and relations have richer renderings in
 * `FieldValue`; this is their text form (titles, sorting, compact lines).
 */
export function formatFieldText(field: ResourceField, value: unknown, options: FormatOptions): string | null {
	if (value == null || value === '') return null;
	const format = fieldFormat(field);
	switch (format) {
		case 'number':
		case 'currency':
		case 'percent': {
			const number = toNumber(value);
			if (number === null) return String(value);
			if (format === 'currency') return numberFormat(options.locale, { style: 'currency', currency: options.currency }).format(number);
			if (format === 'percent') return numberFormat(options.locale, { style: 'percent', maximumFractionDigits: 1 }).format(number);
			return numberFormat(options.locale, field.input === 'integer' ? { maximumFractionDigits: 0 } : { maximumFractionDigits: 4 }).format(number);
		}
		case 'date':
		case 'datetime':
		case 'relative': {
			const parsed = toDate(value);
			if (!parsed) return String(value);
			if (format === 'relative') return relative(parsed.date, options);
			const dayOnly = format === 'date' || parsed.dateOnly;
			// A date-only value is a calendar day, so it is read (and its year compared) in UTC.
			const zone = parsed.dateOnly ? { timeZone: 'UTC' } : {};
			if (options.compact) {
				const now = new Date(options.now ?? Date.now());
				const sameYear = parsed.dateOnly ? parsed.date.getUTCFullYear() === now.getUTCFullYear() : parsed.date.getFullYear() === now.getFullYear();
				return dateFormat(options.locale, {
					month: 'short',
					day: 'numeric',
					...(sameYear ? {} : { year: 'numeric' }),
					...(dayOnly ? {} : { hour: 'numeric', minute: '2-digit' }),
					...zone,
				}).format(parsed.date);
			}
			if (dayOnly) return dateFormat(options.locale, { dateStyle: 'medium', ...zone }).format(parsed.date);
			return dateFormat(options.locale, { dateStyle: 'medium', timeStyle: 'short' }).format(parsed.date);
		}
		case 'boolean':
			return value === true || value === 'true' ? 'Yes' : 'No';
		case 'badge':
			return optionFor(field, value)?.label ?? String(value);
		default:
			if (typeof value === 'object') return JSON.stringify(value);
			return String(value);
	}
}

