/** The column and direction as one compact menu, for widths where headers are folded away. */
export function SortMenu({ resource, sort, onSortChange }: { resource: AnyResource; sort: Sort | undefined; onSortChange: (sort: Sort) => void }) {
	const fields = visibleFields(resource, [...new Set([...resource.columns, ...(resource.defaultSort ? [resource.defaultSort.field] : [])])]).filter(isSortable);
	if (fields.length === 0) return null;
	const active = fields.find((field) => field.name === sort?.field);
	const direction = sort?.direction ?? 'asc';
	const DirectionIcon = direction === 'asc' ? ArrowUpNarrowWideIcon : ArrowDownWideNarrowIcon;
	return (
		<DropdownMenu>
			<DropdownMenuTrigger
				aria-label={active ? `Sort by ${active.label}, ${direction === 'asc' ? 'ascending' : 'descending'}` : 'Sort'}
				className={cn(
					'inline-flex h-7 max-w-40 shrink-0 cursor-pointer items-center gap-1.5 rounded-md border border-border bg-card px-2 text-[0.8125rem] text-foreground shadow-2xs hover:bg-muted data-[popup-open]:bg-muted',
					pressClass,
					focusRingClass,
				)}
			>
				<DirectionIcon aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
				<span aria-hidden="true" className="hidden truncate @md/view:inline">
					{active?.label ?? 'Sort'}
				</span>
			</DropdownMenuTrigger>
			<DropdownMenuContent align="end" className="max-w-64 min-w-44">
				<DropdownMenuLabel>Sort by</DropdownMenuLabel>
				<DropdownMenuRadioGroup value={sort?.field ?? ''} onValueChange={(value) => onSortChange({ field: String(value), direction })}>
					{fields.map((field) => (
						<DropdownMenuRadioItem key={field.name} value={field.name}>
							<span className="truncate">{field.label}</span>
						</DropdownMenuRadioItem>
					))}
				</DropdownMenuRadioGroup>
				<DropdownMenuSeparator />
				<DropdownMenuLabel>Direction</DropdownMenuLabel>
				<DropdownMenuRadioGroup
					value={direction}
					onValueChange={(value) => onSortChange({ field: sort?.field ?? fields[0]!.name, direction: value === 'desc' ? 'desc' : 'asc' })}
				>
					<DropdownMenuRadioItem value="asc">Ascending</DropdownMenuRadioItem>
					<DropdownMenuRadioItem value="desc">Descending</DropdownMenuRadioItem>
				</DropdownMenuRadioGroup>
			</DropdownMenuContent>
		</DropdownMenu>
	);
}

type ListPaginationProps = {
	offset: number;
	limit: number;
	totalCount: number;
	onOffsetChange: (offset: number) => void;
	locale?: string;
	className?: string;
};

/** "26–50 of 1,284" with previous and next. Hidden when everything fits on one page. */
export function ListPagination({ offset, limit, totalCount, onOffsetChange, locale, className }: ListPaginationProps) {
	if (totalCount <= limit && offset === 0) return null;
	const first = totalCount === 0 ? 0 : offset + 1;
	const last = Math.min(offset + limit, totalCount);
	return (
		<nav aria-label="Pagination" className={cn('flex flex-wrap items-center justify-between gap-2', className)}>
			<p className="text-xs text-muted-foreground tabular-nums" aria-live="polite">
				{formatCount(first, locale)}–{formatCount(last, locale)} of {formatCount(totalCount, locale)}
			</p>
			<div className="flex items-center gap-1">
				<Button size="xs" variant="outline" disabled={offset === 0} onClick={() => onOffsetChange(Math.max(0, offset - limit))} aria-label="Previous page">
					<ChevronLeftIcon aria-hidden="true" className="rtl:rotate-180" />
					<span className="hidden @md/view:inline">Previous</span>
				</Button>
				<Button size="xs" variant="outline" disabled={last >= totalCount} onClick={() => onOffsetChange(offset + limit)} aria-label="Next page">
					<span className="hidden @md/view:inline">Next</span>
					<ChevronRightIcon aria-hidden="true" className="rtl:rotate-180" />
				</Button>
			</div>
		</nav>
	);
}

'use client';

import * as React from 'react';

import { RecordDetail } from '@/components/ui/resource-kit/record-detail';
import { ResourcePage } from '@/components/ui/resource-kit/resource-page';
import type { ResourceRouter } from '@/components/ui/resource-kit/types';

/**
 * A router over component state, for demos, stories, tests, and prototypes
 * without a framework: `/<resource>` for a list and `/<resource>/<id>` for a
 * record. Links render as `#/<path>`, so a static page never points outside
 * its base path and a click never leaves the page. Render the screen for its
 * `path` with `MemoryRoute`.
 */
export function useMemoryRouter(initialPath: string) {
	const [path, setPath] = React.useState(initialPath);
	const router = React.useMemo<ResourceRouter>(
		() => ({
			Link: ({ href, onClick, ...rest }) => (
				<a
					{...rest}
					href={`#${href}`}
					onClick={(event) => {
						onClick?.(event);
						if (event.defaultPrevented || event.metaKey || event.ctrlKey) return;
						event.preventDefault();
						setPath(href);
					}}
				/>
			),
			navigate: setPath,
			listHref: (resource) => `/${resource}`,
			detailHref: (resource, id) => `/${resource}/${encodeURIComponent(id)}`,
		}),
		[],
	);
	return { path, setPath, router };
}

/** The screen for a `useMemoryRouter` path: `home` at `/`, a resource's list, or one of its records. */
export function MemoryRoute({ path, home }: { path: string; home?: React.ReactNode }) {
	const [, name, id] = path.split('/');
	if (!name) return home ?? null;
	// Each record and each list mounts fresh, the way a route change would.
	if (id) return <RecordDetail key={path} resource={name} id={decodeURIComponent(id)} />;
	return <ResourcePage key={name} resource={name} />;
}

import type { ListQuery, ListResult, ResourceSource } from '@/components/ui/resource-kit/types';

/** One side of an in-memory many-to-many junction. */
export type MemoryLinkSide = {
	linked(id: string): string[];
	link(id: string, targetIds: string[]): void;
};

const PAIR = '\u0000';

/**
 * An in-memory junction table between two resources. Give `left` to the first
 * resource's many-to-many field and `right` to the second's, and both read the
 * same pairs.
 */
export function createMemoryJunction(pairs: readonly (readonly [string, string])[] = []) {
	const rows = new Set(pairs.map(([left, right]) => `${left}${PAIR}${right}`));
	const side = (index: 0 | 1): MemoryLinkSide => ({
		linked: (id) => [...rows].map((row) => row.split(PAIR)).filter((pair) => pair[index] === id).map((pair) => pair[1 - index]!),
		link: (id, targetIds) => {
			for (const row of [...rows]) if (row.split(PAIR)[index] === id) rows.delete(row);
			for (const targetId of new Set(targetIds)) rows.add(index === 0 ? `${id}${PAIR}${targetId}` : `${targetId}${PAIR}${id}`);
		},
	});
	return { left: side(0), right: side(1) };
}

export type MemorySourceOptions = {
	/** Defaults to "id". */
	primaryKey?: string;
	/** Fields `search` matches, case-insensitively. Defaults to every string field. */
	searchFields?: string[];
	/** Many-to-many fields and the junction side each reads. */
	links?: Record<string, MemoryLinkSide>;
	/** Simulated round-trip in milliseconds. */
	latency?: number;
	/** Id for a created row. Defaults to a random UUID. */
	createId?: () => string;
	/** Fills defaults on create, e.g. `createdAt`. */
	onCreate?: (values: Record<string, unknown>) => Record<string, unknown>;
};

const fold = (value: unknown) => String(value ?? '').normalize('NFKD').toLocaleLowerCase();

function compare(left: unknown, right: unknown): number {
	if (left == null || left === '') return right == null || right === '' ? 0 : 1;
	if (right == null || right === '') return -1;
	if (typeof left === 'number' && typeof right === 'number') return left - right;
	if (typeof left === 'boolean' && typeof right === 'boolean') return Number(left) - Number(right);
	return String(left).localeCompare(String(right), undefined, { numeric: true, sensitivity: 'base' });
}

const copy = <T>(value: T): T => structuredClone(value);

/**
 * A `ResourceSource` over an array, for demos, stories, tests, and prototypes
 * before a backend exists. Search, sort, equality filters, paging, and
 * many-to-many links behave like a real source; rows are copied in and out so
 * callers never share references with the store.
 */
export function createMemorySource<Row extends Record<string, unknown>>(initialRows: readonly Row[], options: MemorySourceOptions = {}): ResourceSource<Row> {
	const { primaryKey = 'id', searchFields, links = {}, latency = 0, createId = () => crypto.randomUUID(), onCreate } = options;
	let rows: Row[] = copy([...initialRows]);
	const wait = () => (latency > 0 ? new Promise((resolve) => setTimeout(resolve, latency)) : Promise.resolve());
	const find = (id: string) => rows.find((row) => String(row[primaryKey]) === id);

	return {
		async list(query: ListQuery): Promise<ListResult<Row>> {
			await wait();
			let result = rows;
			for (const [field, expected] of Object.entries(query.filters ?? {})) {
				result = result.filter((row) => (expected == null ? row[field] == null : String(row[field]) === String(expected)));
			}
			const search = fold(query.search?.trim());
			if (search) {
				result = result.filter((row) => {
					const keys = searchFields ?? Object.keys(row).filter((key) => typeof row[key] === 'string');
					return keys.some((key) => fold(row[key]).includes(search));
				});
			}
			if (query.sort) {
				const { field, direction } = query.sort;
				result = [...result].sort((left, right) => compare(left[field], right[field]) * (direction === 'desc' ? -1 : 1));
			}
			return { rows: copy(result.slice(query.offset, query.offset + query.limit)), totalCount: result.length };
		},
		async get(id) {
			await wait();
			const row = find(id);
			return row ? copy(row) : null;
		},
		async create(values) {
			await wait();
			const base = { [primaryKey]: createId(), ...copy(values) } as Record<string, unknown>;
			const row = (onCreate ? { ...base, ...onCreate(base) } : base) as Row;
			rows = [row, ...rows];
			return copy(row);
		},
		async update(id, patch) {
			await wait();
			const row = find(id);
			if (!row) throw new Error('That record no longer exists.');
			const next = { ...row, ...copy(patch) } as Row;
			rows = rows.map((candidate) => (candidate === row ? next : candidate));
			return copy(next);
		},
		async remove(id) {
			await wait();
			rows = rows.filter((row) => String(row[primaryKey]) !== id);
			for (const side of Object.values(links)) side.link(id, []);
		},
		async link(id, field, targetIds) {
			await wait();
			const side = links[field];
			if (!side) throw new Error(`No link table for ${field}.`);
			side.link(id, targetIds);
		},
		async linked(id, field) {
			await wait();
			return links[field]?.linked(id) ?? [];
		},
	};
}

'use client';

import { keepPreviousData, useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import * as React from 'react';

import { useResourceKit } from '@/components/ui/resource-kit/context';
import { recordId, relatedResourceNames } from '@/components/ui/resource-kit/fields';
import type { Submission } from '@/components/ui/resource-kit/form-values';
import type { AnyResource, ListQuery, ResourceRow } from '@/components/ui/resource-kit/types';

/** Every cache entry of a resource sits under `resourceKeys.all(name)`, so one write can invalidate them together. */
export const resourceKeys = {
	all: (resource: string) => ['resource-kit', resource] as const,
	list: (resource: string, query: ListQuery) => ['resource-kit', resource, 'list', query] as const,
	detail: (resource: string, id: string) => ['resource-kit', resource, 'detail', id] as const,
	linked: (resource: string, id: string, field: string) => ['resource-kit', resource, 'linked', id, field] as const,
};

/** Why a query failed, from its first failed attempt rather than after the retries, so a broken read never passes for an empty one. */
export const queryFailure = (query: { error: unknown; failureReason: unknown }) => query.error ?? query.failureReason;

/** One page of a resource. Keeps the previous page on screen while the next loads. */
export function useResourceList(resource: AnyResource, query: ListQuery, options: { enabled?: boolean } = {}) {
	return useQuery({
		queryKey: resourceKeys.list(resource.name, query),
		queryFn: () => resource.source.list(query),
		placeholderData: keepPreviousData,
		enabled: options.enabled ?? true,
	});
}

/** The query for one record, shared by the detail view and every label that names it. */
export const recordQuery = (resource: AnyResource, id: string) => ({
	queryKey: resourceKeys.detail(resource.name, id),
	queryFn: () => resource.source.get(id),
});

/** The query for the ids linked through a many-to-many field: an empty list when the source cannot say. */
export const linkedQuery = (resource: AnyResource, id: string, field: string) => ({
	queryKey: resourceKeys.linked(resource.name, id, field),
	queryFn: () => (resource.source.linked ? resource.source.linked(id, field) : Promise.resolve([])),
});

export function useResourceRecord(resource: AnyResource, id: string | null | undefined) {
	return useQuery({ ...recordQuery(resource, id ?? ''), enabled: Boolean(id) });
}

/** The ids linked through a many-to-many field, or an empty list when the source cannot say. */
export function useLinkedIds(resource: AnyResource, id: string | null | undefined, field: string, options: { enabled?: boolean } = {}) {
	return useQuery({ ...linkedQuery(resource, id ?? '', field), enabled: Boolean(id) && (options.enabled ?? true) });
}

/** Invalidates a resource and every resource related to it, so lists, details, related lists, and labels refetch. */
export function useInvalidateResource() {
	const queryClient = useQueryClient();
	const { resources } = useResourceKit();
	return React.useCallback(
		(resource: AnyResource) =>
			Promise.all(relatedResourceNames(resource, resources).map((name) => queryClient.invalidateQueries({ queryKey: resourceKeys.all(name) }))),
		[queryClient, resources],
	);
}

type SaveInput = { id?: string; submission: Submission };

/** The record was written but a many-to-many link was not: retry as an edit of `record`, never as a new create. */
export class PartialSaveError extends Error {
	readonly record: ResourceRow;
	readonly field: string;
	constructor(record: ResourceRow, field: string, cause: unknown) {
		super(cause instanceof Error ? cause.message : 'The links could not be saved.', { cause });
		this.name = 'PartialSaveError';
		this.record = record;
		this.field = field;
	}
}

/** Creates or updates a record, then writes its many-to-many links. Resolves with the saved row. */
export function useSaveRecord(resource: AnyResource) {
	const invalidate = useInvalidateResource();
	return useMutation({
		mutationFn: async ({ id, submission }: SaveInput) => {
			const { source } = resource;
			let row: ResourceRow;
			if (id) {
				const hasChanges = Object.keys(submission.values).length > 0;
				row = hasChanges ? await source.update(id, submission.values) : ((await source.get(id)) ?? { [resource.primaryKey]: id });
			} else {
				row = await source.create(submission.values);
			}
			const savedId = id ?? recordId(resource, row);
			const links = Object.entries(submission.links);
			if (links.length > 0) {
				if (!source.link) throw new PartialSaveError(row, links[0]![0], new Error(`${resource.label} cannot link records: the source has no link().`));
				for (const [field, targetIds] of links) {
					try {
						await source.link(savedId, field, targetIds);
					} catch (cause) {
						throw new PartialSaveError(row, field, cause);
					}
				}
			}
			return row;
		},
		onSettled: () => invalidate(resource),
	});
}

export function useDeleteRecord(resource: AnyResource) {
	const invalidate = useInvalidateResource();
	const queryClient = useQueryClient();
	return useMutation({
		mutationFn: (id: string) => resource.source.remove(id),
		onSuccess: (_result, id) => queryClient.removeQueries({ queryKey: resourceKeys.detail(resource.name, id) }),
		onSettled: () => invalidate(resource),
	});
}

'use client';

import { ChevronRightIcon, PencilIcon, SearchXIcon, Trash2Icon } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button, buttonVariants } from '@/components/ui/button';
import { ViewFrame } from '@/components/ui/workspace-kit/primitives';
import { dashedRule, EmptyState, Panel } from '@/components/ui/workspace-kit/surface';
import { useResourceDefinition, useResourceIcon, useResourceKit } from '@/components/ui/resource-kit/context';
import { LoadFailure } from '@/components/ui/resource-kit/failures';
import { FieldValue, linkClass } from '@/components/ui/resource-kit/field-value';
import { detailFields, hasManyRelations, inSentence } from '@/components/ui/resource-kit/fields';
import { useRelationLabels, useRowTitles } from '@/components/ui/resource-kit/labels';
import { useResourceRecord } from '@/components/ui/resource-kit/queries';
import { useRecordDialogs } from '@/components/ui/resource-kit/record-dialogs';
import { RelatedList } from '@/components/ui/resource-kit/related-list';
import type { AnyResource, ResourceField, ResourceRef, ResourceRow } from '@/components/ui/resource-kit/types';

export type RecordDetailProps = {
	resource: ResourceRef;
	id: string;
	/** Rows each related list shows. Defaults to 5. */
	relatedLimit?: number;
	/** Hides edit, delete, and the related lists' create buttons. */
	readOnly?: boolean;
	className?: string;
};

/** Long values read better stacked under their label than squeezed beside it. */
const isLong = (field: ResourceField) => field.input === 'textarea' || field.input === 'json' || Boolean(field.relation?.many);

/**
 * One record: its fields, a list for every resource that belongs to it
 * (has-many), and edit and delete. Deleting returns to the list.
 */
export function RecordDetail({ resource: resourceRef, id, relatedLimit = 5, readOnly = false, className }: RecordDetailProps) {
	const resource = useResourceDefinition(resourceRef);
	const icon = useResourceIcon(resource);
	const { router, resources } = useResourceKit();
	const record = useResourceRecord(resource, id);
	const related = React.useMemo(() => hasManyRelations(resource, resources), [resource, resources]);
	const row = record.data ?? null;
	const records = useRecordDialogs(resource, { record: row, onDeleted: () => router.navigate(router.listHref(resource.name)) });
	const titleOf = useRowTitles(resource, row ? [row] : []);
	const title = row ? (titleOf(row) ?? '…') : '';

	const breadcrumb = (
		<span className="flex min-w-0 items-center gap-1">
			<router.Link href={router.listHref(resource.name)} className={cn(linkClass, 'shrink-0 text-muted-foreground hover:text-foreground hover:no-underline')}>
				{resource.label}
			</router.Link>
			<ChevronRightIcon aria-hidden="true" className="size-3.5 shrink-0 text-subtle-foreground rtl:rotate-180" />
			<span dir="auto" title={title} className="min-w-0 truncate">
				{row ? title : '…'}
			</span>
		</span>
	);

	let body: React.ReactNode;
	if (record.isPending) {
		body = <DetailSkeleton />;
	} else if (record.isError) {
		body = <LoadFailure what={`this ${inSentence(resource.singular)}`} error={record.error} onRetry={() => void record.refetch()} />;
	} else if (!row) {
		body = (
			<EmptyState
				className="rounded-xl bg-card shadow-card"
				icon={SearchXIcon}
				title={`This ${inSentence(resource.singular)} doesn’t exist`}
				description="It may have been deleted, or you may not have access to it."
				action={
					<router.Link href={router.listHref(resource.name)} className={buttonVariants({ size: 'sm', variant: 'outline' })}>
						All {inSentence(resource.label)}
					</router.Link>
				}
			/>
		);
	} else {
		body = (
			<>
				<DetailFields resource={resource} row={row} />
				{related.map((relation) => (
					<RelatedList
						key={`${relation.resource.name}:${relation.field.name}`}
						parent={resource}
						parentId={id}
						relation={relation}
						limit={relatedLimit}
						readOnly={readOnly}
					/>
				))}
			</>
		);
	}

	return (
		<div className={cn('@container/view flex min-h-0 min-w-0 flex-1 flex-col', className)}>
			<ViewFrame
				icon={icon}
				label={title || resource.singular}
				title={breadcrumb}
				actions={
					readOnly || !row ? null : (
						<>
							<Button size="sm" variant="outline" className="h-7" onClick={() => records.edit(row)} aria-label={`Edit ${title}`}>
								<PencilIcon aria-hidden="true" />
								<span className="hidden @md/view:inline">Edit</span>
							</Button>
							<Button size="sm" variant="destructive-outline" className="h-7" onClick={() => records.remove(row)} aria-label={`Delete ${title}`}>
								<Trash2Icon aria-hidden="true" />
								<span className="hidden @md/view:inline">Delete</span>
							</Button>
						</>
					)
				}
				maxWidth="max-w-4xl"
			>
				{body}
			</ViewFrame>
			{row ? records.dialogs : null}
		</div>
	);
}

/** Short fields as label-value rows; long text and linked sets stacked under their labels. */
function DetailFields({ resource, row }: { resource: AnyResource; row: ResourceRow }) {
	const fields = React.useMemo(() => detailFields(resource), [resource]);
	const rows = React.useMemo(() => [row], [row]);
	const relationLabel = useRelationLabels(fields, rows);
	const short = fields.filter((field) => !isLong(field));
	const long = fields.filter(isLong);
	return (
		<Panel title="Details" bodyClassName="flex flex-col gap-4">
			{short.length > 0 ? (
				<dl className="flex flex-col text-[0.8125rem]">
					{short.map((field, index) => (
						<div
							key={field.name}
							className={cn('grid grid-cols-1 gap-x-4 gap-y-0.5 py-2 @md/view:grid-cols-[minmax(0,12rem)_minmax(0,1fr)]', index > 0 && cn('border-t', dashedRule))}
						>
							<dt className="min-w-0 text-muted-foreground [overflow-wrap:anywhere]">{field.label}</dt>
							<dd className="min-w-0 text-foreground">
								<FieldValue resource={resource} field={field} row={row} relation={relationLabel(field, row)} />
							</dd>
						</div>
					))}
				</dl>
			) : null}
			{long.map((field) => (
				<section key={field.name} aria-label={field.label} className={cn('flex flex-col gap-1.5 border-t pt-3 text-[0.8125rem]', dashedRule)}>
					<h3 className="text-muted-foreground">{field.label}</h3>
					<div className="text-foreground">
						<FieldValue resource={resource} field={field} row={row} relation={relationLabel(field, row)} />
					</div>
				</section>
			))}
		</Panel>
	);
}

function DetailSkeleton() {
	return (
		<div aria-busy="true" aria-label="Loading" className="rounded-xl bg-card p-4 shadow-card motion-safe:animate-pulse">
			{Array.from({ length: 5 }, (_, index) => (
				<div key={index} className={cn('flex items-center gap-6 py-3', index > 0 && cn('border-t', dashedRule))}>
					<span className="h-2.5 w-24 rounded-full bg-muted" />
					<span className="h-2.5 w-40 rounded-full bg-muted" />
				</div>
			))}
		</div>
	);
}

'use client';

import * as React from 'react';

import { DeleteDialog } from '@/components/ui/resource-kit/delete-dialog';
import { EntityFormSheet } from '@/components/ui/resource-kit/entity-form-sheet';
import type { AnyResource, ResourceRow } from '@/components/ui/resource-kit/types';

/** A dialog keeps its record while it closes, so its copy does not blank out. */
type DialogState = { open: boolean; record: ResourceRow | null };

const CLOSED: DialogState = { open: false, record: null };

type RecordDialogsOptions = {
	/** Starting values for a new record, e.g. the parent of a related list. */
	defaultValues?: ResourceRow;
	onDeleted?: (id: string) => void;
	/** The record a detail view shows: the dialogs follow its live row instead of the row they opened with. */
	record?: ResourceRow | null;
};

/** The create and edit sheet and the delete confirmation of one resource, with the state that opens them. */
export function useRecordDialogs(resource: AnyResource, { defaultValues, onDeleted, record }: RecordDialogsOptions = {}) {
	const [sheet, setSheet] = React.useState<DialogState>(CLOSED);
	const [deleting, setDeleting] = React.useState<DialogState>(CLOSED);
	const dialogs = (
		<>
			<EntityFormSheet
				resource={resource}
				record={record ?? sheet.record}
				open={sheet.open}
				onOpenChange={(open) => setSheet((current) => ({ ...current, open }))}
				defaultValues={defaultValues}
			/>
			<DeleteDialog
				resource={resource}
				record={record ?? deleting.record}
				open={deleting.open}
				onOpenChange={(open) => setDeleting((current) => ({ ...current, open }))}
				onDeleted={onDeleted}
			/>
		</>
	);
	return {
		create: () => setSheet({ open: true, record: null }),
		edit: (row: ResourceRow) => setSheet({ open: true, record: row }),
		remove: (row: ResourceRow) => setDeleting({ open: true, record: row }),
		dialogs,
	};
}

'use client';

import { PlusIcon } from 'lucide-react';
import * as React from 'react';

import { formatCount } from '@/lib/intl';
import { Button } from '@/components/ui/button';
import { EmptyState, SectionHeading } from '@/components/ui/workspace-kit/surface';
import { useResourceIcon, useResourceKit } from '@/components/ui/resource-kit/context';
import { DataTable } from '@/components/ui/resource-kit/data-table';
import { type HasManyRelation, inSentence } from '@/components/ui/resource-kit/fields';
import { errorMessage } from '@/components/ui/resource-kit/form-values';
import { queryFailure, useResourceList } from '@/components/ui/resource-kit/queries';
import { useRecordDialogs } from '@/components/ui/resource-kit/record-dialogs';
import type { AnyResource, ListQuery } from '@/components/ui/resource-kit/types';

type RelatedListProps = {
	parent: AnyResource;
	parentId: string;
	relation: HasManyRelation;
	limit: number;
	readOnly?: boolean;
};

/**
 * The records of another resource that belong to this one, e.g. a company's
 * contacts: the first few rows, how many there are, and a create button that
 * fills in the parent.
 */
export function RelatedList({ parent, parentId, relation, limit, readOnly }: RelatedListProps) {
	const { resource, field } = relation;
	const { locale } = useResourceKit();
	const icon = useResourceIcon(resource);
	const records = useRecordDialogs(resource, { defaultValues: { [field.name]: parentId } });
	const query: ListQuery = { sort: resource.defaultSort, offset: 0, limit, filters: { [field.name]: parentId } };
	const list = useResourceList(resource, query);
	const failure = queryFailure(list);
	const columns = React.useMemo(() => resource.columns.filter((name) => name !== field.name), [resource.columns, field.name]);
	const total = list.data?.totalCount ?? 0;
	const headingId = React.useId();
	// Two belongs-to fields on one resource pointing here (author, reviewer) need the field to tell their lists apart.
	const title = Object.values(resource.fields).filter((candidate) => candidate.relation?.resource === parent.name && !candidate.relation.many).length > 1
		? `${resource.label} · ${field.label}`
		: resource.label;

	return (
		<section aria-labelledby={headingId} className="flex flex-col gap-3">
			<SectionHeading
				id={headingId}
				title={
					<span className="flex min-w-0 items-baseline gap-1.5">
						<span className="[overflow-wrap:anywhere]">{title}</span>
						{list.data ? <span className="text-xs font-normal text-muted-foreground tabular-nums">{formatCount(total, locale)}</span> : null}
					</span>
				}
				description={list.data && total > limit ? `Showing the first ${formatCount(limit, locale)}.` : undefined}
				actions={
					readOnly ? null : (
						<Button size="xs" variant="outline" onClick={records.create} aria-label={`New ${inSentence(resource.singular)}`}>
							<PlusIcon aria-hidden="true" />
							<span className="hidden @md/view:inline">New {inSentence(resource.singular)}</span>
						</Button>
					)
				}
			/>
			{list.data && total === 0 && !list.isError ? (
				<EmptyState icon={icon} title={`No ${inSentence(resource.label)} yet`} className="rounded-xl bg-card py-6 shadow-card" />
			) : (
				<DataTable
					resource={resource}
					rows={list.data?.rows ?? []}
					columns={columns}
					loading={list.isPending && !list.failureReason}
					error={failure ? `Couldn’t load ${inSentence(resource.label)}: ${errorMessage(failure)}` : undefined}
					skeletonRows={Math.min(limit, 3)}
					onEdit={readOnly ? undefined : records.edit}
					onDelete={readOnly ? undefined : records.remove}
				/>
			)}
			{records.dialogs}
		</section>
	);
}

