	className?: string;
};

export type RelationPickerProps = RelationPickerBaseProps &
	(
		| { multiple?: false; value: string | null; onChange: (value: string | null) => void }
		| { multiple: true; value: readonly string[]; onChange: (value: string[]) => void }
	);

/**
 * Picks related records by searching the target resource as you type
 * (`source.list({ search })`). Single mode holds one id; `multiple` holds a set
 * of ids for a many-to-many field. Selected labels load through `get` once and
 * stay cached.
 */
export function RelationPicker(props: RelationPickerProps) {
	const { resource: resourceRef, labelField, limit = 20, id, placeholder, disabled, invalid, className } = props;
	const target = useResourceDefinition(resourceRef);
	const describedBy = props['aria-describedby'];
	const [open, setOpen] = React.useState(false);
	const [search, setSearch] = React.useState('');
	const debounced = useDebounce(search.trim(), 250);

	// Hosts often pass a fresh array; key the selection by its contents so labels and items stay stable.
	const selectionKey = props.multiple ? props.value.join('\u0000') : (props.value ?? '');
	const selectedIds = React.useMemo(() => (selectionKey ? selectionKey.split('\u0000') : []), [selectionKey]);
	const { labels, missing } = useRecordLabels(target, selectedIds, labelField);

	// A target without search fields is searched among the loaded records instead of by the source.
	const searchable = (target.searchFields?.length ?? 0) > 0;
	const [shown, setShown] = React.useState(limit);
	const [lastSearch, setLastSearch] = React.useState(debounced);
	if (lastSearch !== debounced) {
		setLastSearch(debounced);
		setShown(limit);
	}
	const query: ListQuery = { search: searchable ? debounced || undefined : undefined, sort: target.defaultSort, offset: 0, limit: shown };
	const results = useResourceList(target, query, { enabled: open });

	// Base UI resets the typed text whenever the selected value changes identity, so an option keeps one object per id and label.
	const optionCache = React.useRef(new Map<string, RelationOption>());
	const stableOption = React.useCallback((optionId: string, label: string) => {
		const cached = optionCache.current.get(optionId);
		if (cached?.label === label) return cached;
		const option = { id: optionId, label };
		optionCache.current.set(optionId, option);
		return option;
	}, []);
	const rows = results.data?.rows;
	const titleOf = useRowTitles(target, rows ?? [], labelField);
	const titles = (rows ?? []).map((row) => titleOf(row) ?? '…');
	const titlesKey = titles.join('\u0000');
	const localFilter = searchable ? '' : debounced.toLocaleLowerCase();
	const found = React.useMemo<RelationOption[]>(
		() =>
			(rows ?? [])
				.map((row, index) => stableOption(recordId(target, row), titles[index]!))
				.filter((option) => !localFilter || option.label.toLocaleLowerCase().includes(localFilter)),
		// The titles are read through `titlesKey`, so a new array with the same labels keeps the same options.
		[rows, titlesKey, target, stableOption, localFilter],
	);
	const more = (results.data?.totalCount ?? 0) - (rows?.length ?? 0);
	const selected = React.useMemo<RelationOption[]>(
		() =>
			selectedIds.map((selectedId) =>
				stableOption(selectedId, labels.get(selectedId) ?? found.find((option) => option.id === selectedId)?.label ?? (missing.has(selectedId) ? 'Unavailable' : '…')),
			),
		[selectedIds, labels, missing, found, stableOption],
	);
	// Selected records stay in the list even when the current search does not return them.
	const items = React.useMemo(() => [...found, ...selected.filter((option) => !found.some((candidate) => candidate.id === option.id))], [found, selected]);

	const failure = queryFailure(results);
	const searching = results.isFetching && !failure;
	const status = failure ? (
		<span role="alert" className="flex items-start gap-2 font-normal text-destructive [overflow-wrap:anywhere]">
			<CircleAlertIcon aria-hidden="true" className="mt-0.5 size-3.5 shrink-0" />
			{`Couldn’t load ${inSentence(target.label)}: ${errorMessage(failure)}`}
		</span>
	) : searching ? (
		<span className="flex items-center gap-2">
			<Spinner decorative className="size-3.5" />
			Searching…
		</span>
	) : null;
	const shared = {
		items,
		filter: null,
		open,
		onOpenChange: (next: boolean) => {
			setOpen(next);
			if (!next) setSearch('');
		},
		onInputValueChange: (next: string, details: { reason: string }) => {
			if (details.reason === 'input-change' || details.reason === 'input-clear') setSearch(next);
		},
		itemToStringLabel: (option: RelationOption) => option.label,
		isItemEqualToValue: (option: RelationOption, value: RelationOption) => option.id === value.id,
		disabled,
	};
	const popup = (
		<ComboboxPopup aria-busy={searching || undefined}>
			<ComboboxStatus>{status}</ComboboxStatus>
			<ComboboxEmpty>{searching || failure ? null : debounced ? `No ${inSentence(target.label)} match “${debounced}”.` : `No ${inSentence(target.label)} yet.`}</ComboboxEmpty>
			<ComboboxList>
				{(option: RelationOption) => (
					<ComboboxItem key={option.id} value={option}>
						<span dir="auto" className="block truncate" title={option.label}>
							{option.label}
						</span>
					</ComboboxItem>
				)}
			</ComboboxList>
			{more > 0 && !failure ? (
				<button
					type="button"
					// Keeps focus in the input so the list stays open.
					onMouseDown={(event) => event.preventDefault()}
					onClick={() => setShown((count) => count + limit)}
					className={cn('mx-1 mb-1 cursor-pointer rounded-sm px-2 py-1.5 text-start text-xs text-muted-foreground tabular-nums hover:bg-accent hover:text-foreground', focusRingClass)}
				>
					{results.isFetching ? 'Loading…' : `Show ${formatCount(Math.min(limit, more))} more${more > limit ? ` (${formatCount(more)} left)` : ''}`}
				</button>
			) : null}
		</ComboboxPopup>
	);
	const fallbackPlaceholder = placeholder ?? `Search ${inSentence(target.label)}…`;

	if (props.multiple) {
		const onChange = props.onChange;
		return (
			<Combobox<RelationOption, true>
				{...shared}
				multiple
				value={selected}
				onValueChange={(next, details) => {
					// Escape backs out of a form sheet; it never clears a choice there.
					if (details.reason !== 'escape-key') onChange(next.map((option) => option.id));
				}}
			>
				<ComboboxChips aria-invalid={invalid || undefined} className={className}>
					<ComboboxValue>
						{(value: RelationOption[]) => (
							<>
								{value.map((option) => (
									<ComboboxChip key={option.id} aria-label={option.label}>
										{option.label}
									</ComboboxChip>
								))}
								<ComboboxInput id={id} aria-describedby={describedBy} aria-invalid={invalid || undefined} placeholder={value.length > 0 ? undefined : fallbackPlaceholder} />
							</>
						)}
					</ComboboxValue>
				</ComboboxChips>
				{popup}
			</Combobox>
		);
	}

	const onChange = props.onChange;
	return (
		<Combobox<RelationOption>
			{...shared}
			value={selected[0] ?? null}
			onValueChange={(next, details) => {
				if (details.reason !== 'escape-key') onChange(next?.id ?? null);
			}}
		>
			<ComboboxInput
				id={id}
				aria-describedby={describedBy}
				aria-invalid={invalid || undefined}
				placeholder={fallbackPlaceholder}
				showClear={Boolean(selected[0])}
				className={className}
			/>
			{popup}
		</Combobox>
	);
}

'use client';

import { NavIcon, NavRow, NavSection } from '@/components/ui/workspace-kit/nav';
import { useResourceIcon, useResourceKit } from '@/components/ui/resource-kit/context';
import type { AnyResource } from '@/components/ui/resource-kit/types';

export type ResourceNavProps = {
	/** Resource names in nav order; defaults to every resource the provider holds. */
	resources?: readonly string[];
	/** The current path, to mark the matching resource active. */
	activeHref?: string;
	/** Icon-rail mode, from the workspace sidebar's render props. */
	collapsed: boolean;
	/** Closes the navigation drawer after a choice. */
	onNavigate?: () => void;
	/** Heading above the rows. */
	title?: string;
};

function ResourceNavRow({ resource, active, collapsed, onNavigate }: { resource: AnyResource; active: boolean; collapsed: boolean; onNavigate?: () => void }) {
	const { router } = useResourceKit();
	const icon = useResourceIcon(resource);
	return (
		<NavRow
			label={resource.label}
			collapsed={collapsed}
			active={active}
			leading={<NavIcon icon={icon} active={active} />}
			href={router.listHref(resource.name)}
			onClick={onNavigate}
			renderLink={(props) => <router.Link {...props} />}
		/>
	);
}

/**
 * Sidebar rows for the app's resources, built on the workspace nav: one link
 * per resource with its icon, the active one marked from the current path.
 * Render it inside a `SidebarFrame`.
 */
export function ResourceNav({ resources: order, activeHref, collapsed, onNavigate, title }: ResourceNavProps) {
	const { resources, byName, router } = useResourceKit();
	const shown = order ? order.flatMap((name) => byName.get(name) ?? []) : resources;
	return (
		<NavSection title={title} collapsed={collapsed}>
			{shown.map((resource) => {
				const href = router.listHref(resource.name);
				const active = Boolean(activeHref) && (activeHref === href || activeHref!.startsWith(`${href}/`));
				return <ResourceNavRow key={resource.name} resource={resource} active={active} collapsed={collapsed} onNavigate={onNavigate} />;
			})}
		</NavSection>
	);
}

'use client';

import { PlusIcon, SearchXIcon } from 'lucide-react';
import * as React from 'react';

import { formatCount } from '@/lib/intl';
import { useDebounce } from '@/hooks/use-debounce';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { SearchField, ViewFrame } from '@/components/ui/workspace-kit/primitives';
import { EmptyState } from '@/components/ui/workspace-kit/surface';
import { useResourceDefinition, useResourceIcon, useResourceKit } from '@/components/ui/resource-kit/context';
import { DataTable } from '@/components/ui/resource-kit/data-table';
import { LoadFailure } from '@/components/ui/resource-kit/failures';
import { inSentence } from '@/components/ui/resource-kit/fields';
import { errorMessage } from '@/components/ui/resource-kit/form-values';
import { ListPagination, SortMenu } from '@/components/ui/resource-kit/list-controls';
import { useResourceList } from '@/components/ui/resource-kit/queries';
import { useRecordDialogs } from '@/components/ui/resource-kit/record-dialogs';
import type { ListQuery, ResourceRef } from '@/components/ui/resource-kit/types';

export type ResourcePageProps = {
	resource: ResourceRef;
	/** Rows per page. Defaults to 25. */
	pageSize?: number;
	/** Fixed equality filters, e.g. `{ status: 'open' }`. */
	filters?: Record<string, unknown>;
	/** Hides the create button and the edit and delete actions. */
	readOnly?: boolean;
	className?: string;
};

/**
 * A resource's list screen: the view header with the count and a create
 * button, search and sort, the table, pagination, and empty, no-match, and
 * error states. Create and edit open in a sheet; delete asks first. Every
 * write refreshes the list.
 */
export function ResourcePage({ resource: resourceRef, pageSize = 25, filters, readOnly = false, className }: ResourcePageProps) {
	const resource = useResourceDefinition(resourceRef);
	const icon = useResourceIcon(resource);
	const { locale } = useResourceKit();
	const [search, setSearch] = React.useState('');
	const debounced = useDebounce(search.trim(), 250);
	const [sort, setSort] = React.useState(resource.defaultSort);
	const [offset, setOffset] = React.useState(0);
	const records = useRecordDialogs(resource);

	// A new search or sort starts from the first page, adjusted during render rather than in an effect.
	const pageKey = `${debounced}\u0000${sort?.field}\u0000${sort?.direction}`;
	const [lastPageKey, setLastPageKey] = React.useState(pageKey);
	if (lastPageKey !== pageKey) {
		setLastPageKey(pageKey);
		setOffset(0);
	}

	const query: ListQuery = { search: debounced || undefined, sort, offset, limit: pageSize, filters };
	const list = useResourceList(resource, query);
	const rows = list.data?.rows ?? [];
	const totalCount = list.data?.totalCount ?? 0;
	const noun = inSentence(resource.label);
	// Without search fields the source has nothing to search, so the box would only ever fail or match everything.
	const searchable = (resource.searchFields?.length ?? 0) > 0;
	const singular = inSentence(resource.singular);

	// Deleting the last row of a later page steps back a page.
	if (list.data && rows.length === 0 && offset > 0 && !list.isPlaceholderData) setOffset(Math.max(0, offset - pageSize));

	// A failed request is shown as soon as it fails, even while it retries: rows kept from an earlier search
	// or page would otherwise read as this query's answer.
	const failure = list.error ?? (list.isPlaceholderData || !list.data ? list.failureReason : null);
	const stale = list.isError && list.data && !list.isPlaceholderData;

	let body: React.ReactNode;
	if (failure && !stale) {
		body = <LoadFailure what={noun} error={failure} onRetry={() => void list.refetch()} />;
	} else if (list.data && totalCount === 0 && !debounced) {
		body = (
			<EmptyState
				className="rounded-xl bg-card shadow-card"
				icon={icon}
				title={`No ${noun} yet`}
				description={readOnly ? undefined : `Create the first ${singular} to see it here.`}
				action={
					readOnly ? undefined : (
						<Button size="sm" onClick={records.create}>
							<PlusIcon aria-hidden="true" />
							New {singular}
						</Button>
					)
				}
			/>
		);
	} else if (list.data && totalCount === 0) {
		body = (
			<EmptyState
				className="rounded-xl bg-card shadow-card"
				icon={SearchXIcon}
				title={<span className="[overflow-wrap:anywhere]">No {noun} match “{debounced}”</span>}
				description="Try a different search."
				action={
					<Button size="sm" variant="outline" onClick={() => setSearch('')}>
						Clear search
					</Button>
				}
			/>
		);
	} else {
		body = (
			<DataTable
				resource={resource}
				rows={rows}
				error={stale ? `Couldn’t refresh ${noun}: ${errorMessage(list.error)}` : undefined}
				loading={list.isPending}
				skeletonRows={Math.min(pageSize, 8)}
				sort={sort}
				onSortChange={setSort}
				onEdit={readOnly ? undefined : records.edit}
				onDelete={readOnly ? undefined : records.remove}
				className={cn(list.isPlaceholderData && 'opacity-70 transition-opacity')}
			/>
		);
	}

	return (
		<div className={cn('@container/view flex min-h-0 min-w-0 flex-1 flex-col', className)}>
			<ViewFrame
				icon={icon}
				label={resource.label}
				title={
					<span className="flex min-w-0 items-baseline gap-1.5">
						<span className="truncate">{resource.label}</span>
						{list.data ? <span className="shrink-0 text-xs font-normal text-muted-foreground tabular-nums">{formatCount(totalCount, locale)}</span> : null}
					</span>
				}
				actions={
					readOnly ? null : (
						<Button size="sm" className="h-7" onClick={records.create} aria-label={`New ${singular}`}>
							<PlusIcon aria-hidden="true" />
							<span className="hidden @md/view:inline">New {singular}</span>
						</Button>
					)
				}
				className="gap-3 @3xl/view:py-5"
			>
				{list.data && totalCount === 0 && !debounced ? null : (
					<div className="flex items-center gap-2">
						{searchable ? (
							<SearchField
								label={`Search ${noun}`}
								placeholder={`Search ${noun}`}
								value={search}
								onChange={(event) => setSearch(event.target.value)}
								className="min-w-0 flex-1 @xl/view:w-64 @xl/view:flex-none"
							/>
						) : null}
						<SortMenu resource={resource} sort={sort} onSortChange={setSort} />
					</div>
				)}
				{body}
				{list.data ? <ListPagination offset={offset} limit={pageSize} totalCount={totalCount} onOffsetChange={setOffset} locale={locale} /> : null}
			</ViewFrame>
			{records.dialogs}
		</div>
	);
}

import type * as React from 'react';

/** How a field is edited. */
export type FieldInput =
	| 'text'
	| 'textarea'
	| 'email'
	| 'url'
	| 'number'
	| 'integer'
	| 'currency'
	| 'boolean'
	| 'date'
	| 'datetime'
	| 'time'
	| 'select'
	| 'relation'
	| 'json'
	| 'uuid';

/** How a field reads in lists and on the detail view. */
export type FieldFormat = 'text' | 'number' | 'currency' | 'percent' | 'date' | 'datetime' | 'relative' | 'boolean' | 'badge';

export type FieldTone = 'neutral' | 'info' | 'success' | 'warning' | 'danger';

export type FieldOption = { value: string; label: string; tone?: FieldTone };

export type ResourceField = {
	/** Row key as the data source returns it (camelCase). */
	name: string;
	label: string;
	input: FieldInput;
	/** List and detail display; defaults from `input`. */
	format?: FieldFormat;
	required?: boolean;
	/** Shown, never written (e.g. createdAt). */
	readOnly?: boolean;
	/** Never shown (e.g. ownerId). */
	hidden?: boolean;
	description?: string;
	placeholder?: string;
	options?: FieldOption[];
	relation?: {
		/** Target resource name. */
		resource: string;
		/** Many-to-many through a junction: values come from `source.linked` and are written with `source.link`. */
		many?: boolean;
		/** Defaults to the target's `titleField`. */
		labelField?: string;
	};
};

export type ListQuery = {
	search?: string;
	sort?: { field: string; direction: 'asc' | 'desc' };
	offset: number;
	limit: number;
	/** Equality filters, e.g. `{ status: 'open' }`. */
	filters?: Record<string, unknown>;
};

export type ListResult<Row> = { rows: Row[]; totalCount: number };

export interface ResourceSource<Row extends Record<string, unknown> = Record<string, unknown>> {
	list(query: ListQuery): Promise<ListResult<Row>>;
	get(id: string): Promise<Row | null>;
	create(values: Partial<Row>): Promise<Row>;
	update(id: string, patch: Partial<Row>): Promise<Row>;
	remove(id: string): Promise<void>;
	/** Many-to-many: replaces the set of linked ids for one relation field. */
	link?(id: string, field: string, targetIds: string[]): Promise<void>;
	linked?(id: string, field: string): Promise<string[]>;
}

export type ResourceDefinition<Row extends Record<string, unknown> = Record<string, unknown>> = {
	/** Stable id, kebab-case plural (the route segment). */
	name: string;
	/** Plural display name, e.g. "Shifts". */
	label: string;
	/** Singular display name, e.g. "Shift". */
	singular: string;
	/** Lucide icon name, resolved through the provider's `icons` map. */
	icon?: string;
	/** Usually "id". */
	primaryKey: string;
	/** Row label in pickers, breadcrumbs, and titles. */
	titleField: string;
	/** List columns, in order. */
	columns: string[];
	/** Create and edit fields, in order. */
	formFields: string[];
	/** Detail fields; defaults to every visible field. */
	detailFields?: string[];
	/** Text fields the toolbar search covers. */
	searchFields?: string[];
	defaultSort?: { field: string; direction: 'asc' | 'desc' };
	fields: Record<string, ResourceField>;
	source: ResourceSource<Row>;
};

/** Identity helper that keeps a resource definition typed against its row. */
export function defineResource<Row extends Record<string, unknown>>(definition: ResourceDefinition<Row>): ResourceDefinition<Row> {
	return definition;
}

/** The anchor props the kit hands the router's link: `href` plus any other `<a>` prop. */
export type ResourceLinkProps = Omit<React.ComponentProps<'a'>, 'href'> & { href: string };

/** The host's router, injected so the kit never imports one. */
export type ResourceRouter = {
	/** Must forward every prop to its anchor: nav rows set `aria-current` and a click that closes the drawer. */
	Link: React.ComponentType<ResourceLinkProps>;
	navigate(href: string): void;
	/** e.g. "/shifts" */
	listHref(resource: string): string;
	/** e.g. "/shifts/<id>" */
	detailHref(resource: string, id: string): string;
};

/** A resource with any row shape, as the provider holds them. */
export type AnyResource = ResourceDefinition<any>;

/** A row as the kit reads it. */
export type ResourceRow = Record<string, unknown>;

/** A resource passed by name (resolved through the provider) or by definition. */
export type ResourceRef = string | AnyResource;
